package tools.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;
import tools.jackson.core.util.ByteArrayBuilder;

public class Base64VariantTest {

    @Test
    public void testConstructorWithInvalidAlphabet() {
        try {
            new Base64Variant("test", "abcdefghijklmnopqrstuvwxyz0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ+/", true, '=', 76);
            fail("Should throw IllegalArgumentException for invalid alphabet length");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Base64Alphabet length must be exactly 64"));
        }
    }

    @Test
    public void testDecodeBase64Char() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        assertEquals(0, variant.decodeBase64Char('A'));
        assertEquals(25, variant.decodeBase64Char('Z'));
        assertEquals(26, variant.decodeBase64Char('a'));
        assertEquals(51, variant.decodeBase64Char('z'));
        assertEquals(52, variant.decodeBase64Char('0'));
        assertEquals(62, variant.decodeBase64Char('9'));
        assertEquals(63, variant.decodeBase64Char('+'));
        assertEquals(62, variant.decodeBase64Char('/'));
        assertEquals(Base64Variant.BASE64_VALUE_INVALID, variant.decodeBase64Char(' '));
        assertEquals(Base64Variant.BASE64_VALUE_INVALID, variant.decodeBase64Char('='));
        assertEquals(Base64Variant.BASE64_VALUE_INVALID, variant.decodeBase64Char((char) 128));
    }

    @Test
    public void testEncodeBase64BitsAsChar() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        assertEquals('A', variant.encodeBase64BitsAsChar(0));
        assertEquals('Z', variant.encodeBase64BitsAsChar(25));
        assertEquals('a', variant.encodeBase64BitsAsChar(26));
        assertEquals('z', variant.encodeBase64BitsAsChar(51));
        assertEquals('0', variant.encodeBase64BitsAsChar(52));
        assertEquals('9', variant.encodeBase64BitsAsChar(62));
        assertEquals('+', variant.encodeBase64BitsAsChar(63));
        assertEquals('/', variant.encodeBase64BitsAsChar(62));
    }

    @Test
    public void testEncodeBase64Chunk() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        char[] buffer = new char[4];
        int outPtr = variant.encodeBase64Chunk(0xABCDEF, buffer, 0);
        assertEquals(4, outPtr);
        assertEquals("ABCD", new String(buffer));
    }

    @Test
    public void testEncodeBase64Partial() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        char[] buffer = new char[4];
        int outPtr = variant.encodeBase64Partial(0xABC, 1, buffer, 0);
        assertEquals(4, outPtr);
        assertEquals("AB==", new String(buffer));

        buffer = new char[4];
        outPtr = variant.encodeBase64Partial(0xABCD, 2, buffer, 0);
        assertEquals(4, outPtr);
        assertEquals("ABC=", new String(buffer));
    }

    @Test
    public void testEncodeAndDecode() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        byte[] input = {0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F};
        String encoded = variant.encode(input);
        byte[] decoded = variant.decode(encoded);
        assertArrayEquals(input, decoded);
    }

    @Test
    public void testDecodeWithPadding() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        String input = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";
        byte[] decoded = variant.decode(input);
        assertEquals(24, decoded.length);
    }

    @Test
    public void testDecodeWithoutPadding() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", false, '=', 76);
        String input = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        byte[] decoded = variant.decode(input);
        assertEquals(24, decoded.length);
    }

    @Test
    public void testDecodeWithInvalidPadding() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        try {
            variant.decode("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/X");
            fail("Should throw IllegalArgumentException for invalid padding");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("expected padding character"));
        }
    }

    @Test
    public void testDecodeWithMissingPadding() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        try {
            variant.decode("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/");
            fail("Should throw IllegalArgumentException for missing padding");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("expects padding"));
        }
    }

    @Test
    public void testDecodeWithInvalidCharacter() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        try {
            variant.decode("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/X");
            fail("Should throw IllegalArgumentException for invalid character");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Illegal character"));
        }
    }

    @Test
    public void testDecodeWithWhitespace() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        String input = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";
        byte[] decoded = variant.decode(input.replace("=", " = "));
        assertEquals(24, decoded.length);
    }

    @Test
    public void testEqualsAndHashCode() {
        Base64Variant variant1 = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        Base64Variant variant2 = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        assertEquals(variant1, variant2);
        assertEquals(variant1.hashCode(), variant2.hashCode());

        Base64Variant variant3 = new Base64Variant("test2", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        assertNotEquals(variant1, variant3);
        assertNotEquals(variant1.hashCode(), variant3.hashCode());
    }

    @Test
    public void testToString() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        assertEquals("test", variant.toString());
    }

    @Test
    public void testGetters() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        assertEquals("test", variant.getName());
        assertTrue(variant.usesPadding());
        assertEquals('=', variant.getPaddingChar());
        assertEquals((byte) '=', variant.getPaddingByte());
        assertEquals(76, variant.getMaxLineLength());
        assertEquals(Base64Variant.PaddingReadBehaviour.PADDING_REQUIRED, variant.paddingReadBehaviour());
        assertTrue(variant.requiresPaddingOnRead());
        assertTrue(variant.acceptsPaddingOnRead());
    }

    @Test
    public void testWithPaddingAllowed() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        Base64Variant newVariant = variant.withPaddingAllowed();
        assertEquals(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED, newVariant.paddingReadBehaviour());
        assertNotSame(variant, newVariant);
    }

    @Test
    public void testWithPaddingRequired() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        Base64Variant newVariant = variant.withPaddingRequired();
        assertEquals(Base64Variant.PaddingReadBehaviour.PADDING_REQUIRED, newVariant.paddingReadBehaviour());
        assertSame(variant, newVariant);
    }

    @Test
    public void testWithPaddingForbidden() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        Base64Variant newVariant = variant.withPaddingForbidden();
        assertEquals(Base64Variant.PaddingReadBehaviour.PADDING_FORBIDDEN, newVariant.paddingReadBehaviour());
        assertNotSame(variant, newVariant);
    }

    @Test
    public void testWithWritePadding() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        Base64Variant newVariant = variant.withWritePadding(false);
        assertFalse(newVariant.usesPadding());
        assertNotSame(variant, newVariant);
    }

    @Test
    public void testDecodeWithByteArrayBuilder() {
        Base64Variant variant = new Base64Variant("test", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        ByteArrayBuilder builder = new ByteArrayBuilder();
        variant.decode("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=", builder);
        byte[] result = builder.toByteArray();
        assertEquals(24, result.length);
    }
}

