package tools.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class JsonPointerTest {

    @Test
    public void testCompileEmptyPointer() {
        JsonPointer pointer = JsonPointer.compile("");
        assertTrue(pointer.matches());
        assertEquals("", pointer.toString());
    }

    @Test
    public void testCompileNullPointer() {
        JsonPointer pointer = JsonPointer.compile(null);
        assertTrue(pointer.matches());
        assertEquals("", pointer.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCompileInvalidPointer() {
        JsonPointer.compile("invalid");
    }

    @Test
    public void testCompileSimplePointer() {
        JsonPointer pointer = JsonPointer.compile("/test");
        assertFalse(pointer.matches());
        assertEquals("/test", pointer.toString());
        assertEquals("test", pointer.getMatchingProperty());
        assertEquals(-1, pointer.getMatchingIndex());
    }

    @Test
    public void testCompilePointerWithIndex() {
        JsonPointer pointer = JsonPointer.compile("/0");
        assertFalse(pointer.matches());
        assertEquals("/0", pointer.toString());
        assertEquals(-1, pointer.getMatchingProperty());
        assertEquals(0, pointer.getMatchingIndex());
    }

    @Test
    public void testCompilePointerWithEscapedCharacters() {
        JsonPointer pointer = JsonPointer.compile("/a~1b~0c");
        assertFalse(pointer.matches());
        assertEquals("/a/b~c", pointer.toString());
        assertEquals("a/b~c", pointer.getMatchingProperty());
        assertEquals(-1, pointer.getMatchingIndex());
    }

    @Test
    public void testMatchesProperty() {
        JsonPointer pointer = JsonPointer.compile("/test");
        assertTrue(pointer.matchesProperty("test"));
        assertFalse(pointer.matchesProperty("other"));
    }

    @Test
    public void testMatchProperty() {
        JsonPointer pointer = JsonPointer.compile("/test/value");
        JsonPointer result = pointer.matchProperty("test");
        assertNotNull(result);
        assertEquals("/value", result.toString());
    }

    @Test
    public void testMatchPropertyNoMatch() {
        JsonPointer pointer = JsonPointer.compile("/test/value");
        JsonPointer result = pointer.matchProperty("other");
        assertNull(result);
    }

    @Test
    public void testMatchesElement() {
        JsonPointer pointer = JsonPointer.compile("/0");
        assertTrue(pointer.matchesElement(0));
        assertFalse(pointer.matchesElement(1));
    }

    @Test
    public void testMatchElement() {
        JsonPointer pointer = JsonPointer.compile("/0/value");
        JsonPointer result = pointer.matchElement(0);
        assertNotNull(result);
        assertEquals("/value", result.toString());
    }

    @Test
    public void testMatchElementNoMatch() {
        JsonPointer pointer = JsonPointer.compile("/0/value");
        JsonPointer result = pointer.matchElement(1);
        assertNull(result);
    }

    @Test
    public void testAppendProperty() {
        JsonPointer pointer = JsonPointer.compile("/test");
        JsonPointer result = pointer.appendProperty("value");
        assertEquals("/test/value", result.toString());
    }

    @Test
    public void testAppendPropertyNull() {
        JsonPointer pointer = JsonPointer.compile("/test");
        JsonPointer result = pointer.appendProperty(null);
        assertEquals("/test", result.toString());
    }

    @Test
    public void testAppendIndex() {
        JsonPointer pointer = JsonPointer.compile("/test");
        JsonPointer result = pointer.appendIndex(0);
        assertEquals("/test/0", result.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAppendNegativeIndex() {
        JsonPointer pointer = JsonPointer.compile("/test");
        pointer.appendIndex(-1);
    }

    @Test
    public void testAppend() {
        JsonPointer pointer1 = JsonPointer.compile("/test");
        JsonPointer pointer2 = JsonPointer.compile("/value");
        JsonPointer result = pointer1.append(pointer2);
        assertEquals("/test/value", result.toString());
    }

    @Test
    public void testAppendEmpty() {
        JsonPointer pointer = JsonPointer.compile("/test");
        JsonPointer result = pointer.append(JsonPointer.empty());
        assertEquals("/test", result.toString());
    }

    @Test
    public void testLast() {
        JsonPointer pointer = JsonPointer.compile("/test/value");
        JsonPointer result = pointer.last();
        assertEquals("/value", result.toString());
    }

    @Test
    public void testLastEmpty() {
        JsonPointer pointer = JsonPointer.empty();
        JsonPointer result = pointer.last();
        assertNull(result);
    }

    @Test
    public void testTail() {
        JsonPointer pointer = JsonPointer.compile("/test/value");
        JsonPointer result = pointer.tail();
        assertEquals("/value", result.toString());
    }

    @Test
    public void testTailEmpty() {
        JsonPointer pointer = JsonPointer.empty();
        JsonPointer result = pointer.tail();
        assertNull(result);
    }

    @Test
    public void testHead() {
        JsonPointer pointer = JsonPointer.compile("/test/value");
        JsonPointer result = pointer.head();
        assertEquals("/test", result.toString());
    }

    @Test
    public void testHeadEmpty() {
        JsonPointer pointer = JsonPointer.empty();
        JsonPointer result = pointer.head();
        assertEquals("", result.toString());
    }

    @Test
    public void testEquals() {
        JsonPointer pointer1 = JsonPointer.compile("/test");
        JsonPointer pointer2 = JsonPointer.compile("/test");
        assertEquals(pointer1, pointer2);
    }

    @Test
    public void testNotEquals() {
        JsonPointer pointer1 = JsonPointer.compile("/test");
        JsonPointer pointer2 = JsonPointer.compile("/value");
        assertNotEquals(pointer1, pointer2);
    }

    @Test
    public void testHashCode() {
        JsonPointer pointer1 = JsonPointer.compile("/test");
        JsonPointer pointer2 = JsonPointer.compile("/test");
        assertEquals(pointer1.hashCode(), pointer2.hashCode());
    }

    @Test
    public void testToString() {
        JsonPointer pointer = JsonPointer.compile("/test");
        assertEquals("/test", pointer.toString());
    }

    @Test
    public void testLength() {
        JsonPointer pointer = JsonPointer.compile("/test");
        assertEquals(5, pointer.length());
    }

    @Test
    public void testMayMatchProperty() {
        JsonPointer pointer = JsonPointer.compile("/test");
        assertTrue(pointer.mayMatchProperty());
    }

    @Test
    public void testMayMatchElement() {
        JsonPointer pointer = JsonPointer.compile("/0");
        assertTrue(pointer.mayMatchElement());
    }
}

