    public void testConstructorWithJsonPointer() {
        JsonPointer pointer = JsonPointer.compile("/path/to/value");
        JsonPointerBasedFilter filter = new JsonPointerBasedFilter(pointer);
        assertNotNull(filter);
        assertEquals("[JsonPointerFilter at: /path/to/value]", filter.toString());
    }

