        assertEquals("[JsonPointerFilter at: /path/to/array/*]", filter.toString());
    }

    @Test
    public void testIncludePropertyMatching() {
        JsonPointer pointer = JsonPointer.compile("/path/to/value");
        JsonPointerBasedFilter filter = new JsonPointerBasedFilter(pointer);
        TokenFilter result = filter.includeProperty("value");
        assertNotNull(result);
        assertTrue(result == TokenFilter.INCLUDE_ALL);
    }

    @Test
    public void testIncludePropertyNonMatching() {
        JsonPointer pointer = JsonPointer.compile("/path/to/value");
