        TokenFilter result = filter.includeProperty("other");
        assertNull(result);
    }

    @Test
    public void testIncludeElementMatching() {
        JsonPointer pointer = JsonPointer.compile("/path/to/array/0");
        JsonPointerBasedFilter filter = new JsonPointerBasedFilter(pointer);
        TokenFilter result = filter.includeElement(0);
        assertNotNull(result);
        assertTrue(result == TokenFilter.INCLUDE_ALL);
    }

    @Test
    public void testIncludeElementNonMatching() {
        JsonPointer pointer = JsonPointer.compile("/path/to/array/0");
        JsonPointerBasedFilter filter = new JsonPointerBasedFilter(pointer);
        TokenFilter result = filter.includeElement(1);
        assertNull(result);
    }

    @Test
    public void testIncludeAllElements() {
        JsonPointer pointer = JsonPointer.compile("/path/to/array/*");
        JsonPointerBasedFilter filter = new JsonPointerBasedFilter(pointer, true);
        TokenFilter result = filter.includeElement(0);
        assertNotNull(result);
        assertTrue(result == TokenFilter.INCLUDE_ALL);
    }

    @Test
    public void testFilterStartObject() {
        JsonPointer pointer = JsonPointer.compile("/path/to/value");
        JsonPointerBasedFilter filter = new JsonPointerBasedFilter(pointer);
        TokenFilter result = filter.filterStartObject();
        assertSame(filter, result);
    }

    @Test
    public void testFilterStartArray() {
        JsonPointer pointer = JsonPointer.compile("/path/to/value");
        JsonPointerBasedFilter filter = new JsonPointerBasedFilter(pointer);
        TokenFilter result = filter.filterStartArray();
        assertSame(filter, result);
    }

    @Test
    public void testIncludeScalar() {
