        TokenFilterContext context = TokenFilterContext.createRootContext(filter);
        context._type = TokenFilterContext.TYPE_ARRAY;

        JsonToken token = context.nextTokenToRead();
        assertEquals(JsonToken.START_ARRAY, token);
        assertTrue(context._startHandled);
    }

