        context.setPropertyName("testName");

        JsonToken token = context.nextTokenToRead();
        assertEquals(JsonToken.PROPERTY_NAME, token);
        assertFalse(context._needToHandleName);
    }

    @Test
    public void testFindChildOf() {
        TokenFilter filter = TokenFilter.INCLUDE_ALL;
        TokenFilterContext root = TokenFilterContext.createRootContext(filter);
        TokenFilterContext child = root.createChildObjectContext(filter, new Object(), true);

        TokenFilterContext result = child.findChildOf(root);
        assertEquals(child, result);

        TokenFilterContext grandchild = child.createChildArrayContext(filter, new Object(), true);
        result = grandchild.findChildOf(child);
        assertEquals(grandchild, result);

        result = grandchild.findChildOf(root);
        assertEquals(child, result);

        assertNull(grandchild.findChildOf(new TokenFilterContext(TYPE_ROOT, null, filter, null, true)));
    }

    @Test
    public void testToString() {
        TokenFilter filter = TokenFilter.INCLUDE_ALL;
        TokenFilterContext root = TokenFilterContext.createRootContext(filter);
        assertEquals("/", root.toString());

        TokenFilterContext objectContext = root.createChildObjectContext(filter, new Object(), true);
        objectContext.setPropertyName("testName");
        assertEquals("{ \"testName\" }", objectContext.toString());

        TokenFilterContext arrayContext = root.createChildArrayContext(filter, new Object(), true);
        assertEquals("[0]", arrayContext.toString());
    }
}

