        assertNull(grandchild.findChildOf(new TokenFilterContext(TokenFilterContext.TYPE_ROOT, null, filter, null, true)));
    }

    @Test
    public void testToString() {
        TokenFilter filter = TokenFilter.INCLUDE_ALL;
        TokenFilterContext root = TokenFilterContext.createRootContext(filter);
        assertEquals("/", root.toString());

        TokenFilterContext objectContext = root.createChildObjectContext(filter, new Object(), true);
        objectContext.setPropertyName("testName");
        assertEquals("{ \"testName\" }", objectContext.toString());

        TokenFilterContext arrayContext = root.createChildArrayContext(filter, new Object(), true);
        assertEquals("[0]", arrayContext.toString());
    }
}

