package tools.jackson.core.io;

import static org.junit.Assert.*;
import org.junit.Test;

public class CharTypesTest {

    @Test
    public void testGetInputCodeLatin1() {
        int[] codes = CharTypes.getInputCodeLatin1();
        assertNotNull(codes);
        assertEquals(256, codes.length);
        assertEquals(-1, codes[0]); // Control character
        assertEquals(1, codes['"']); // Quote character
        assertEquals(1, codes['\\']); // Backslash
        assertEquals(0, codes[' ']); // Space
    }

    @Test
    public void testGetInputCodeUtf8() {
        int[] codes = CharTypes.getInputCodeUtf8();
        assertNotNull(codes);
        assertEquals(256, codes.length);
        assertEquals(2, codes[0xC0]); // 2-byte UTF-8 start
        assertEquals(3, codes[0xE0]); // 3-byte UTF-8 start
        assertEquals(4, codes[0xF0]); // 4-byte UTF-8 start
        assertEquals(-1, codes[0xFF]); // Invalid UTF-8 start
    }

    @Test
    public void testGetInputCodeLatin1JsNames() {
        int[] codes = CharTypes.getInputCodeLatin1JsNames();
        assertNotNull(codes);
        assertEquals(256, codes.length);
        assertEquals(0, codes['A']); // Valid JS identifier part
        assertEquals(0, codes['@']); // Special JS name char
        assertEquals(-1, codes[' ']); // Invalid JS name char
    }

    @Test
    public void testGetInputCodeUtf8JsNames() {
        int[] codes = CharTypes.getInputCodeUtf8JsNames();
        assertNotNull(codes);
        assertEquals(256, codes.length);
        assertEquals(0, codes[0xC0]); // Valid UTF-8 start for JS names
        assertEquals(0, codes['@']); // Special JS name char
        assertEquals(-1, codes[' ']); // Invalid JS name char
    }

    @Test
    public void testGetInputCodeComment() {
        int[] codes = CharTypes.getInputCodeComment();
        assertNotNull(codes);
        assertEquals(256, codes.length);
        assertEquals(-1, codes[0]); // Invalid control char
        assertEquals(0, codes[' ']); // Valid whitespace
        assertEquals('\n', codes['\n']); // Line feed
        assertEquals('*', codes['*']); // Comment end marker
    }

    @Test
    public void testGetInputCodeWS() {
        int[] codes = CharTypes.getInputCodeWS();
        assertNotNull(codes);
        assertEquals(256, codes.length);
        assertEquals(-1, codes[0]); // Invalid control char
        assertEquals(1, codes[' ']); // Valid whitespace
        assertEquals('\n', codes['\n']); // Line feed
        assertEquals('/', codes['/']); // Comment start marker
    }

    @Test
    public void testGet7BitOutputEscapes() {
        int[] escapes = CharTypes.get7BitOutputEscapes();
        assertNotNull(escapes);
        assertEquals(128, escapes.length);
        assertEquals(CharacterEscapes.ESCAPE_STANDARD, escapes[0]); // Control char
        assertEquals('"', escapes['"']); // Quote char
        assertEquals(0, escapes[' ']); // Space
    }

    @Test
    public void testGet7BitOutputEscapesWithSlash() {
        int[] escapes = CharTypes.get7BitOutputEscapes('"', true);
        assertNotNull(escapes);
        assertEquals(128, escapes.length);
        assertEquals(CharacterEscapes.ESCAPE_STANDARD, escapes[0]); // Control char
        assertEquals('"', escapes['"']); // Quote char
        assertEquals('/', escapes['/']); // Escaped slash
        assertEquals(0, escapes[' ']); // Space
    }

    @Test
    public void testCharToHex() {
        assertEquals(0, CharTypes.charToHex('0'));
        assertEquals(9, CharTypes.charToHex('9'));
        assertEquals(10, CharTypes.charToHex('a'));
        assertEquals(10, CharTypes.charToHex('A'));
        assertEquals(15, CharTypes.charToHex('f'));
        assertEquals(15, CharTypes.charToHex('F'));
        assertEquals(-1, CharTypes.charToHex('G')); // Invalid hex char
    }

    @Test
    public void testHexToChar() {
        assertEquals('0', CharTypes.hexToChar(0));
        assertEquals('9', CharTypes.hexToChar(9));
        assertEquals('a', CharTypes.hexToChar(10));
        assertEquals('A', CharTypes.hexToChar(10));
        assertEquals('f', CharTypes.hexToChar(15));
        assertEquals('F', CharTypes.hexToChar(15));
    }

    @Test
    public void testAppendQuoted() {
        StringBuilder sb = new StringBuilder();
        CharTypes.appendQuoted(sb, "test");
        assertEquals("\"test\"", sb.toString());

        sb = new StringBuilder();
        CharTypes.appendQuoted(sb, "te\"st");
        assertEquals("\"te\\\"st\"", sb.toString());

        sb = new StringBuilder();
        CharTypes.appendQuoted(sb, "te\\st");
        assertEquals("\"te\\\\st\"", sb.toString());

        sb = new StringBuilder();
        CharTypes.appendQuoted(sb, "te\nst");
        assertEquals("\"te\\nst\"", sb.toString());

        sb = new StringBuilder();
        CharTypes.appendQuoted(sb, "te\u0000st");
        assertEquals("\"te\\u0000st\"", sb.toString());
    }

    @Test
    public void testCopyHexChars() {
        char[] upper = CharTypes.copyHexChars(true);
        assertEquals("0123456789ABCDEF", new String(upper));

        char[] lower = CharTypes.copyHexChars(false);
        assertEquals("0123456789abcdef", new String(lower));
    }

    @Test
    public void testCopyHexBytes() {
        byte[] upper = CharTypes.copyHexBytes(true);
        assertArrayEquals("0123456789ABCDEF".getBytes(), upper);

        byte[] lower = CharTypes.copyHexBytes(false);
        assertArrayEquals("0123456789abcdef".getBytes(), lower);
    }
}

