package tools.jackson.core.io;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.File;
import java.io.IOException;
import java.net.URI;
import java.net.URL;
import tools.jackson.core.ErrorReportConfiguration;

public class ContentReferenceTest {

    @Test
    public void testUnknownContent() {
        ContentReference unknown = ContentReference.unknown();
        assertNotNull(unknown);
        assertFalse(unknown.hasTextualContent());
        assertEquals("UNKNOWN", unknown.buildSourceDescription());
    }

    @Test
    public void testRedactedContent() {
        ContentReference redacted = ContentReference.redacted();
        assertNotNull(redacted);
        assertFalse(redacted.hasTextualContent());
        assertEquals("REDACTED (`StreamReadFeature.INCLUDE_SOURCE_IN_LOCATION` disabled)",
                     redacted.buildSourceDescription());
    }

    @Test
    public void testRawReferenceWithTextContent() {
        String content = "test content";
        ContentReference ref = ContentReference.rawReference(true, content);
        assertNotNull(ref);
        assertTrue(ref.hasTextualContent());
        assertEquals(content, ref.getRawContent());
    }

    @Test
    public void testRawReferenceWithBinaryContent() {
        byte[] content = "binary content".getBytes();
        ContentReference ref = ContentReference.rawReference(false, content);
        assertNotNull(ref);
        assertFalse(ref.hasTextualContent());
        assertArrayEquals(content, (byte[]) ref.getRawContent());
    }

    @Test
    public void testContentReferenceConstruction() {
        String content = "test content";
        ErrorReportConfiguration config = ErrorReportConfiguration.defaults();
        ContentReference ref = ContentReference.construct(true, content, 0, 5, config);
        assertNotNull(ref);
        assertTrue(ref.hasTextualContent());
        assertEquals(content.substring(0, 5), ref.getRawContent());
        assertEquals(0, ref.contentOffset());
        assertEquals(5, ref.contentLength());
    }

    @Test
    public void testContentReferenceWithNullContent() {
        ContentReference ref = ContentReference.construct(false, null, ErrorReportConfiguration.defaults());
        assertNotNull(ref);
        assertNull(ref.getRawContent());
        assertEquals("UNKNOWN", ref.buildSourceDescription());
    }

    @Test
    public void testContentReferenceWithFileContent() {
        File file = new File("test.txt");
        ContentReference ref = ContentReference.rawReference(false, file);
        assertNotNull(ref);
        assertEquals(file, ref.getRawContent());
        assertEquals("(" + file.getClass().getSimpleName() + ")", ref.buildSourceDescription());
    }

    @Test
    public void testContentReferenceWithURLContent() {
        try {
            URL url = new URL("http://example.com");
            ContentReference ref = ContentReference.rawReference(false, url);
            assertNotNull(ref);
            assertEquals(url, ref.getRawContent());
            assertEquals("(" + url.getClass().getSimpleName() + ")", ref.buildSourceDescription());
        } catch (IOException e) {
            fail("Failed to create URL for test");
        }
    }

    @Test
    public void testContentReferenceWithURIContent() {
        URI uri = URI.create("http://example.com");
        ContentReference ref = ContentReference.rawReference(false, uri);
        assertNotNull(ref);
        assertEquals(uri, ref.getRawContent());
        assertEquals("(" + uri.getClass().getSimpleName() + ")", ref.buildSourceDescription());
    }

    @Test
    public void testContentReferenceWithCharArray() {
        char[] content = "test content".toCharArray();
        ContentReference ref = ContentReference.rawReference(true, content);
        assertNotNull(ref);
        assertArrayEquals(content, (char[]) ref.getRawContent());
        assertEquals("(" + content.getClass().getSimpleName() + ")", ref.buildSourceDescription());
    }

    @Test
    public void testContentReferenceWithByteArray() {
        byte[] content = "binary content".getBytes();
        ContentReference ref = ContentReference.rawReference(false, content);
        assertNotNull(ref);
        assertArrayEquals(content, (byte[]) ref.getRawContent());
        assertEquals("(" + content.getClass().getSimpleName() + ")[14 bytes]", ref.buildSourceDescription());
    }

    @Test
    public void testContentReferenceWithStringContent() {
        String content = "test content";
        ContentReference ref = ContentReference.rawReference(true, content);
        assertNotNull(ref);
        assertEquals(content, ref.getRawContent());
        assertEquals("(" + content.getClass().getSimpleName() + ")\"test content\"", ref.buildSourceDescription());
    }

    @Test
    public void testContentReferenceWithTruncatedContent() {
        String longContent = "a".repeat(1000);
        ErrorReportConfiguration config = new ErrorReportConfiguration.Builder()
                .maxRawContentLength(10)
                .build();
        ContentReference ref = ContentReference.construct(true, longContent, 0, 1000, config);
        assertNotNull(ref);
        assertEquals("(" + longContent.getClass().getSimpleName() + ")\"a".repeat(10) + "[truncated 990 chars]", ref.buildSourceDescription());
    }

    @Test
    public void testContentReferenceEquals() {
        String content = "test content";
        ContentReference ref1 = ContentReference.rawReference(true, content);
        ContentReference ref2 = ContentReference.rawReference(true, content);
        assertEquals(ref1, ref2);

        ContentReference ref3 = ContentReference.rawReference(false, content);
        assertNotEquals(ref1, ref3);

        ContentReference ref4 = ContentReference.unknown();
        assertNotEquals(ref1, ref4);
    }

    @Test
    public void testContentReferenceHashCode() {
        String content = "test content";
        ContentReference ref1 = ContentReference.rawReference(true, content);
        ContentReference ref2 = ContentReference.rawReference(true, content);
        assertEquals(ref1.hashCode(), ref2.hashCode());

        ContentReference ref3 = ContentReference.rawReference(false, content);
        assertNotEquals(ref1.hashCode(), ref3.hashCode());
    }

    @Test
    public void testContentReferenceSerialization() {
        String content = "test content";
        ContentReference ref = ContentReference.rawReference(true, content);

        // Test that serialization doesn't throw exceptions
        try {
            java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
            java.io.ObjectOutputStream oos = new java.io.ObjectOutputStream(baos);
            oos.writeObject(ref);
            oos.close();

            java.io.ByteArrayInputStream bais = new java.io.ByteArrayInputStream(baos.toByteArray());
            java.io.ObjectInputStream ois = new java.io.ObjectInputStream(bais);
            ContentReference deserialized = (ContentReference) ois.readObject();
            ois.close();

            assertEquals(ContentReference.UNKNOWN_CONTENT, deserialized);
        } catch (IOException | ClassNotFoundException e) {
            fail("Serialization failed: " + e.getMessage());
        }
    }
}

