package tools.jackson.core.io;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayOutputStream;
import java.io.DataOutput;
import java.io.IOException;

public class DataOutputAsStreamTest {

    @Test
    public void testWriteSingleByte() throws IOException {
        ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
        DataOutput dataOutput = new DataOutputStream(byteStream);
        DataOutputAsStream outputAsStream = new DataOutputAsStream(dataOutput);

        outputAsStream.write(65); // 'A'

        byte[] result = byteStream.toByteArray();
        assertEquals(1, result.length);
        assertEquals(65, result[0]);
    }

    @Test
    public void testWriteByteArray() throws IOException {
        ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
        DataOutput dataOutput = new DataOutputStream(byteStream);
        DataOutputAsStream outputAsStream = new DataOutputAsStream(dataOutput);

        byte[] data = {65, 66, 67}; // 'A', 'B', 'C'
        outputAsStream.write(data);

        byte[] result = byteStream.toByteArray();
        assertArrayEquals(data, result);
    }

    @Test
    public void testWriteByteArrayWithOffsetAndLength() throws IOException {
        ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
        DataOutput dataOutput = new DataOutputStream(byteStream);
        DataOutputAsStream outputAsStream = new DataOutputAsStream(dataOutput);

        byte[] data = {65, 66, 67, 68, 69}; // 'A', 'B', 'C', 'D', 'E'
        outputAsStream.write(data, 1, 3); // 'B', 'C', 'D'

        byte[] expected = {66, 67, 68};
        byte[] result = byteStream.toByteArray();
        assertArrayEquals(expected, result);
    }

    @Test(expected = IOException.class)
    public void testWriteWithNullArray() throws IOException {
        ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
        DataOutput dataOutput = new DataOutputStream(byteStream);
        DataOutputAsStream outputAsStream = new DataOutputAsStream(dataOutput);

        outputAsStream.write((byte[]) null);
    }

    @Test(expected = IOException.class)
    public void testWriteWithInvalidOffsetAndLength() throws IOException {
        ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
        DataOutput dataOutput = new DataOutputStream(byteStream);
        DataOutputAsStream outputAsStream = new DataOutputAsStream(dataOutput);

        byte[] data = {65, 66, 67};
        outputAsStream.write(data, 2, 2); // offset + length > array length
    }
}

