package tools.jackson.core.io;

import static org.junit.Assert.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.runners.MockitoJUnitRunner;

@RunWith(MockitoJUnitRunner.class)
public class JsonStringEncoderTest {

    private static final JsonStringEncoder encoder = JsonStringEncoder.getInstance();

    @Test
    public void testQuoteAsCharArray() {
        assertArrayEquals(new char[] {'"', 'h', 'e', 'l', 'l', 'o', '"'}, encoder.quoteAsCharArray("hello"));
        assertArrayEquals(new char[] {'"', '\\', 'n', '"'}, encoder.quoteAsCharArray("\n"));
        assertArrayEquals(new char[] {'"', '\\', 'u', '0', '0', '2', '0', '"'}, encoder.quoteAsCharArray("\u0020"));
        assertArrayEquals(new char[] {'"', '\\', 'u', '0', '0', 'a', '0', '"'}, encoder.quoteAsCharArray("\n"));
    }

    @Test
    public void testQuoteAsString() {
        StringBuilder sb = new StringBuilder();
        encoder.quoteAsString("hello", sb);
        assertEquals("\"hello\"", sb.toString());

        sb = new StringBuilder();
        encoder.quoteAsString("\n", sb);
        assertEquals("\"\n\"", sb.toString());

        sb = new StringBuilder();
        encoder.quoteAsString("\u0020", sb);
        assertEquals("\" \", sb.toString());
    }

    @Test
    public void testQuoteAsUTF8() {
        assertArrayEquals(new byte[]{'"', 'h', 'e', 'l', 'l', 'o', '"'}, encoder.quoteAsUTF8("hello"));
        assertArrayEquals(new byte[]{'"', '\\', 'n', '"'}, encoder.quoteAsUTF8("\n"));
        assertArrayEquals(new byte[]{'"', '\\', 'u', '0', '0', '2', '0', '"'}, encoder.quoteAsUTF8("\u0020"));
    }

    @Test
    public void testEncodeAsUTF8() {
        assertArrayEquals(new byte[]{'h', 'e', 'l', 'l', 'o'}, encoder.encodeAsUTF8("hello"));
        assertArrayEquals(new byte[]{'\n'}, encoder.encodeAsUTF8("\n"));
        assertArrayEquals(new byte[]{'\u0020'}, encoder.encodeAsUTF8("\u0020"));
    }

    @Test
    public void testInitialBufferSizes() {
        assertEquals(16, JsonStringEncoder._initialCharBufSize(0));
        assertEquals(16, JsonStringEncoder._initialCharBufSize(10));
        assertEquals(20, JsonStringEncoder._initialCharBufSize(100));
        assertEquals(32000, JsonStringEncoder._initialCharBufSize(1000000));

        assertEquals(24, JsonStringEncoder._initialByteBufSize(0));
        assertEquals(24, JsonStringEncoder._initialByteBufSize(10));
        assertEquals(30, JsonStringEncoder._initialByteBufSize(100));
        assertEquals(32000, JsonStringEncoder._initialByteBufSize(1000000));
    }

