package tools.jackson.core.io;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

public class MergedStreamTest {

    @Test
    public void testConstructorWithNullContext() {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        byte[] buf = new byte[10];
        MergedStream merged = new MergedStream(null, in, buf, 0, 10);
        assertNotNull(merged);
    }

    @Test
    public void testAvailableWithBufferedData() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        byte[] buf = new byte[10];
        MergedStream merged = new MergedStream(null, in, buf, 0, 10);
        assertEquals(10, merged.available());
    }

    @Test
    public void testAvailableAfterReadingBufferedData() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        byte[] buf = new byte[10];
        MergedStream merged = new MergedStream(null, in, buf, 0, 10);
        merged.read(new byte[5]);
        assertEquals(5, merged.available());
    }

    @Test
    public void testAvailableAfterExhaustingBufferedData() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[10]);
        byte[] buf = new byte[10];
        MergedStream merged = new MergedStream(null, in, buf, 0, 10);
        merged.read(new byte[10]);
        assertEquals(10, merged.available());
    }

    @Test
    public void testReadByte() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        byte[] buf = new byte[]{1, 2, 3};
        MergedStream merged = new MergedStream(null, in, buf, 0, 3);
        assertEquals(1, merged.read());
        assertEquals(2, merged.read());
        assertEquals(3, merged.read());
        assertEquals(-1, merged.read());
    }

    @Test
    public void testReadByteArray() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        byte[] buf = new byte[]{1, 2, 3, 4, 5};
        MergedStream merged = new MergedStream(null, in, buf, 0, 5);
        byte[] result = new byte[3];
        assertEquals(3, merged.read(result));
        assertArrayEquals(new byte[]{1, 2, 3}, result);
    }

    @Test
    public void testReadByteArrayWithOffset() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        byte[] buf = new byte[]{1, 2, 3, 4, 5};
        MergedStream merged = new MergedStream(null, in, buf, 0, 5);
        byte[] result = new byte[5];
        assertEquals(2, merged.read(result, 2, 2));
        assertArrayEquals(new byte[]{0, 0, 1, 2, 0}, result);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testReadByteArrayWithInvalidOffset() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        byte[] buf = new byte[5];
        MergedStream merged = new MergedStream(null, in, buf, 0, 5);
        merged.read(new byte[1], 1, 1);
    }

    @Test
    public void testSkip() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        byte[] buf = new byte[]{1, 2, 3, 4, 5};
        MergedStream merged = new MergedStream(null, in, buf, 0, 5);
        assertEquals(2L, merged.skip(2));
        assertEquals(2, merged.available());
    }

    @Test
    public void testSkipBeyondBufferedData() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[10]);
        byte[] buf = new byte[5];
        MergedStream merged = new MergedStream(null, in, buf, 0, 5);
        assertEquals(7L, merged.skip(7));
    }

    @Test
    public void testClose() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        byte[] buf = new byte[5];
        MergedStream merged = new MergedStream(null, in, buf, 0, 5);
        merged.close();
        assertEquals(-1, merged.read());
    }

    @Test
    public void testMarkAndReset() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        byte[] buf = new byte[]{1, 2, 3, 4, 5};
        MergedStream merged = new MergedStream(null, in, buf, 0, 5);
        merged.mark(10);
        merged.read();
        merged.reset();
        assertEquals(1, merged.read());
    }

    @Test
    public void testMarkSupported() {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        byte[] buf = new byte[5];
        MergedStream merged = new MergedStream(null, in, buf, 0, 5);
        assertFalse(merged.markSupported());
    }
}

