package tools.jackson.core.io;

import org.junit.Test;
import static org.junit.Assert.*;

public class NumberInputTest {

    @Test
    public void testParseIntCharArray() {
        char[] chars = "123456789".toCharArray();
        assertEquals(123456789, NumberInput.parseInt(chars, 0, 9));
    }

    @Test
    public void testParseIntCharArrayWithSign() {
        char[] chars = "+123456789".toCharArray();
        assertEquals(123456789, NumberInput.parseInt(chars, 0, 10));
    }

    @Test
    public void testParseIntString() {
        assertEquals(12345, NumberInput.parseInt("12345"));
        assertEquals(-12345, NumberInput.parseInt("-12345"));
        assertEquals(12345, NumberInput.parseInt("+12345"));
    }

    @Test
    public void testParseIntStringWithNonDigits() {
        assertEquals(123, NumberInput.parseInt("123.45"));
        assertEquals(123, NumberInput.parseInt("123e4"));
    }

    @Test
    public void testParseLongCharArray() {
        char[] chars = "1234567890123456789".toCharArray();
        assertEquals(1234567890123456789L, NumberInput.parseLong(chars, 0, 19));
    }

    @Test
    public void testParseLong19() {
        char[] chars = "1234567890123456789".toCharArray();
        assertEquals(1234567890123456789L, NumberInput.parseLong19(chars, 0, false));
        assertEquals(-1234567890123456789L, NumberInput.parseLong19(chars, 0, true));
    }

    @Test
    public void testInLongRange() {
        char[] chars = "9223372036854775807".toCharArray();
        assertTrue(NumberInput.inLongRange(chars, 0, 19, false));
        assertFalse(NumberInput.inLongRange(chars, 0, 19, true));

        chars = "9223372036854775808".toCharArray();
        assertFalse(NumberInput.inLongRange(chars, 0, 19, false));
    }

    @Test
    public void testParseAsInt() {
        assertEquals(42, NumberInput.parseAsInt("42", 0));
        assertEquals(0, NumberInput.parseAsInt(null, 0));
        assertEquals(0, NumberInput.parseAsInt("", 0));
        assertEquals(42, NumberInput.parseAsInt("42.5", 0));
        assertEquals(42, NumberInput.parseAsInt("42e1", 0));
    }

    @Test
    public void testParseAsLong() {
        assertEquals(42L, NumberInput.parseAsLong("42", 0L));
        assertEquals(0L, NumberInput.parseAsLong(null, 0L));
        assertEquals(0L, NumberInput.parseAsLong("", 0L));
        assertEquals(42L, NumberInput.parseAsLong("42.5", 0L));
        assertEquals(420L, NumberInput.parseAsLong("42e1", 0L));
    }

    @Test
    public void testParseDouble() {
        assertEquals(42.5, NumberInput.parseDouble("42.5", false), 0.0001);
        assertEquals(42.5, NumberInput.parseDouble("42.5", true), 0.0001);
        assertEquals(42.5, NumberInput.parseDouble("42.5", false), 0.0001);
    }

    @Test
    public void testParseFloat() {
        assertEquals(42.5f, NumberInput.parseFloat("42.5", false), 0.0001f);
        assertEquals(42.5f, NumberInput.parseFloat("42.5", true), 0.0001f);
    }

    @Test
    public void testParseBigDecimal() {
        assertEquals(new java.math.BigDecimal("123456789012345678901234567890.12345678901234567890"),
                     NumberInput.parseBigDecimal("123456789012345678901234567890.12345678901234567890", false));
    }

    @Test
    public void testParseBigInteger() {
        assertEquals(new java.math.BigInteger("123456789012345678901234567890"),
                     NumberInput.parseBigInteger("123456789012345678901234567890", false));
    }

    @Test
    public void testLooksLikeValidNumber() {
        assertTrue(NumberInput.looksLikeValidNumber("123"));
        assertTrue(NumberInput.looksLikeValidNumber("+123"));
        assertTrue(NumberInput.looksLikeValidNumber("-123"));
        assertTrue(NumberInput.looksLikeValidNumber("123.45"));
        assertTrue(NumberInput.looksLikeValidNumber("123e4"));
        assertTrue(NumberInput.looksLikeValidNumber("123."));
        assertFalse(NumberInput.looksLikeValidNumber(""));
        assertFalse(NumberInput.looksLikeValidNumber("123a"));
        assertFalse(NumberInput.looksLikeValidNumber("123."));
    }
}

