package tools.jackson.core.io;

import org.junit.Test;
import static org.junit.Assert.*;
import tools.jackson.core.JacksonException;
import tools.jackson.core.util.BufferRecycler;

public class SegmentedStringWriterTest {

    @Test
    public void testConstructor() {
        BufferRecycler br = new BufferRecycler();
        SegmentedStringWriter writer = new SegmentedStringWriter(br);
        assertNotNull(writer);
        assertNotNull(writer.bufferRecycler());
    }

    @Test
    public void testWriteAndGetAndClear() throws JacksonException {
        BufferRecycler br = new BufferRecycler();
        SegmentedStringWriter writer = new SegmentedStringWriter(br);

        // Test writing a single character
        writer.write('a');
        assertEquals("a", writer.getAndClear());

        // Test writing a string
        writer.write("hello");
        assertEquals("hello", writer.getAndClear());

        // Test writing a char array
        char[] chars = {'t', 'e', 's', 't'};
        writer.write(chars);
        assertEquals("test", writer.getAndClear());

        // Test writing a string with offset and length
        writer.write("abcdef", 1, 3);
        assertEquals("bcd", writer.getAndClear());

        // Test writing multiple characters
        writer.write('x');
        writer.write('y');
        writer.write('z');
        assertEquals("xyz", writer.getAndClear());

        // Test writing a string with append
        writer.append("appended");
        assertEquals("appended", writer.getAndClear());

        // Test writing a char sequence
        CharSequence cs = "char sequence";
        writer.append(cs);
        assertEquals("char sequence", writer.getAndClear());

        // Test writing a char sequence with offset and length
        writer.append(cs, 5, 8);
        assertEquals("sequence", writer.getAndClear());
    }

    @Test
    public void testMultipleWrites() throws JacksonException {
        BufferRecycler br = new BufferRecycler();
        SegmentedStringWriter writer = new SegmentedStringWriter(br);

        writer.write("first");
        writer.write("second");
        assertEquals("firstsecond", writer.getAndClear());
    }

    @Test
    public void testEmptyWrites() throws JacksonException {
        BufferRecycler br = new BufferRecycler();
        SegmentedStringWriter writer = new SegmentedStringWriter(br);

        assertEquals("", writer.getAndClear());
        writer.write("");
        assertEquals("", writer.getAndClear());
        writer.write("".toCharArray());
        assertEquals("", writer.getAndClear());
        writer.write("".toCharArray(), 0, 0);
        assertEquals("", writer.getAndClear());
        writer.write("", 0, 0);
        assertEquals("", writer.getAndClear());
    }

    @Test
    public void testIdempotentGetAndClear() throws JacksonException {
        BufferRecycler br = new BufferRecycler();
        SegmentedStringWriter writer = new SegmentedStringWriter(br);

        writer.write("test");
        assertEquals("test", writer.getAndClear());
        assertEquals("", writer.getAndClear()); // Should return empty string after clear
    }

    @Test(expected = JacksonException.class)
    public void testMaxStringLengthViolation() throws JacksonException {
        BufferRecycler br = new BufferRecycler();
        SegmentedStringWriter writer = new SegmentedStringWriter(br);

        // Create a very long string
        StringBuilder longString = new StringBuilder();
        for (int i = 0; i < 1000000; i++) {
            longString.append("a");
        }

        writer.write(longString.toString());
        writer.getAndClear(); // This should throw JacksonException due to max string length
    }
}

