        writer.write("Hello, 世界!");
        writer.flush();

        byte[] expected = new byte[]{
            'H', 'e', 'l', 'l', 'o', ',', ' ', '世', (byte)0xE7, (byte)0x95, (byte)0x8C, '!'
        };
