        IOContext context = new IOContext(null, null, null, null, null, false, null);
        UTF8Writer writer = new UTF8Writer(context, out);

        writer.write("Test");
        writer.close();

        assertArrayEquals("Test".getBytes(), out.toByteArray());
    }

    @Test
    public void testAppend() throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        IOContext context = new IOContext(null, null, null, null, null, false, null);
        UTF8Writer writer = new UTF8Writer(context, out);

        writer.append('A').append('B');
        writer.flush();

        assertArrayEquals(new byte[]{'A', 'B'}, out.toByteArray());
    }
}

