package tools.jackson.core.json;

import static org.junit.Assert.*;
import org.junit.Test;
import tools.jackson.core.JsonParser;
import tools.jackson.core.JsonGenerator;
import tools.jackson.core.TokenStreamLocation;

public class DupDetectorTest {

    @Test
    public void testIsDupWithNoNames() {
        DupDetector detector = DupDetector.rootDetector(null);
        assertFalse(detector.isDup("name1"));
        assertFalse(detector.isDup("name2"));
    }

    @Test
    public void testIsDupWithOneName() {
        DupDetector detector = DupDetector.rootDetector(null);
        assertFalse(detector.isDup("name1"));
        assertTrue(detector.isDup("name1"));
        assertFalse(detector.isDup("name2"));
    }

    @Test
    public void testIsDupWithTwoNames() {
        DupDetector detector = DupDetector.rootDetector(null);
        assertFalse(detector.isDup("name1"));
        assertFalse(detector.isDup("name2"));
        assertTrue(detector.isDup("name1"));
        assertTrue(detector.isDup("name2"));
        assertFalse(detector.isDup("name3"));
    }

    @Test
    public void testIsDupWithManyNames() {
        DupDetector detector = DupDetector.rootDetector(null);
        assertFalse(detector.isDup("name1"));
        assertFalse(detector.isDup("name2"));
        assertFalse(detector.isDup("name3"));
        assertTrue(detector.isDup("name1"));
        assertTrue(detector.isDup("name2"));
        assertTrue(detector.isDup("name3"));
        assertFalse(detector.isDup("name4"));
    }

    @Test
    public void testReset() {
        DupDetector detector = DupDetector.rootDetector(null);
        assertFalse(detector.isDup("name1"));
        assertTrue(detector.isDup("name1"));
        detector.reset();
        assertFalse(detector.isDup("name1"));
    }

    @Test
    public void testFindLocationWithParser() {
        JsonParser parser = null; // Mock or real parser instance
        DupDetector detector = DupDetector.rootDetector(parser);
        TokenStreamLocation location = detector.findLocation();
        assertNotNull(location);
    }

    @Test
    public void testFindLocationWithGenerator() {
        JsonGenerator generator = null; // Mock or real generator instance
        DupDetector detector = DupDetector.rootDetector(generator);
        TokenStreamLocation location = detector.findLocation();
        assertNull(location); // Generators don't have location information
    }

    @Test
    public void testChildDetector() {
        DupDetector parent = DupDetector.rootDetector(null);
        DupDetector child = parent.child();
        assertNotSame(parent, child);
        assertFalse(child.isDup("name1"));
    }

    @Test
    public void testGetSource() {
        JsonParser parser = null; // Mock or real parser instance
        DupDetector detector = DupDetector.rootDetector(parser);
        assertSame(parser, detector.getSource());
    }
}

