package tools.jackson.core.json;

import static org.junit.Assert.*;
import org.junit.Test;
import tools.jackson.core.JsonEncoding;
import tools.jackson.core.JsonFactory;
import tools.jackson.core.JsonGenerator;
import tools.jackson.core.JsonParser;
import tools.jackson.core.JsonReadFeature;
import tools.jackson.core.JsonWriteFeature;
import tools.jackson.core.ObjectReadContext;
import tools.jackson.core.ObjectWriteContext;
import tools.jackson.core.io.CharacterEscapes;
import tools.jackson.core.sym.BinaryNameMatcher;
import tools.jackson.core.util.DefaultPrettyPrinter;
import tools.jackson.core.util.Named;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.Reader;
import java.io.StringReader;
import java.io.StringWriter;
import java.io.Writer;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public class JsonFactoryTest {

    @Test
    public void testDefaultConstructor() {
        JsonFactory factory = new JsonFactory();
        assertNotNull(factory);
        assertEquals(JsonFactory.FORMAT_NAME_JSON, factory.getFormatName());
        assertEquals(JsonReadFeature.class, factory.getFormatReadFeatureType());
        assertEquals(JsonWriteFeature.class, factory.getFormatWriteFeatureType());
        assertFalse(factory.isEnabled(JsonReadFeature.IGNORE_UNDEFINED));
        assertTrue(factory.isEnabled(JsonWriteFeature.QUOTE_PROPERTY_NAMES));
    }

    @Test
    public void testCopyConstructor() {
        JsonFactory original = new JsonFactory();
        JsonFactory copy = original.copy();
        assertNotNull(copy);
        assertEquals(original.getFormatName(), copy.getFormatName());
        assertEquals(original.getFormatReadFeatureType(), copy.getFormatReadFeatureType());
        assertEquals(original.getFormatWriteFeatureType(), copy.getFormatWriteFeatureType());
        assertEquals(original.isEnabled(JsonReadFeature.IGNORE_UNDEFINED), copy.isEnabled(JsonReadFeature.IGNORE_UNDEFINED));
        assertEquals(original.isEnabled(JsonWriteFeature.QUOTE_PROPERTY_NAMES), copy.isEnabled(JsonWriteFeature.QUOTE_PROPERTY_NAMES));
    }

    @Test
    public void testBuilder() {
        JsonFactory factory = JsonFactory.builder()
                .enable(JsonReadFeature.IGNORE_UNDEFINED)
                .disable(JsonWriteFeature.QUOTE_PROPERTY_NAMES)
                .build();
        assertNotNull(factory);
        assertTrue(factory.isEnabled(JsonReadFeature.IGNORE_UNDEFINED));
        assertFalse(factory.isEnabled(JsonWriteFeature.QUOTE_PROPERTY_NAMES));
    }

    @Test
    public void testBuilderWithJackson2Defaults() {
        JsonFactory factory = JsonFactory.builderWithJackson2Defaults().build();
        assertNotNull(factory);
        assertFalse(factory.isEnabled(JsonWriteFeature.ESCAPE_FORWARD_SLASHES));
        assertFalse(factory.isEnabled(JsonWriteFeature.COMBINE_UNICODE_SURROGATES_IN_UTF8));
    }

    @Test
    public void testCreateParserFromString() throws Exception {
        JsonFactory factory = new JsonFactory();
        String json = "{\"name\":\"John\", \"age\":30}";
        JsonParser parser = factory.createParser(ObjectReadContext.empty(), json);
        assertNotNull(parser);
        parser.close();
    }

    @Test
    public void testCreateParserFromReader() throws Exception {
        JsonFactory factory = new JsonFactory();
        String json = "{\"name\":\"John\", \"age\":30}";
        Reader reader = new StringReader(json);
        JsonParser parser = factory.createParser(ObjectReadContext.empty(), reader);
        assertNotNull(parser);
        parser.close();
    }

    @Test
    public void testCreateParserFromInputStream() throws Exception {
        JsonFactory factory = new JsonFactory();
        String json = "{\"name\":\"John\", \"age\":30}";
        InputStream input = new ByteArrayInputStream(json.getBytes("UTF-8"));
        JsonParser parser = factory.createParser(ObjectReadContext.empty(), input);
        assertNotNull(parser);
        parser.close();
    }

    @Test
    public void testCreateParserFromByteArray() throws Exception {
        JsonFactory factory = new JsonFactory();
        String json = "{\"name\":\"John\", \"age\":30}";
        byte[] bytes = json.getBytes("UTF-8");
        JsonParser parser = factory.createParser(ObjectReadContext.empty(), bytes);
        assertNotNull(parser);
        parser.close();
    }

    @Test
    public void testCreateParserFromCharArray() throws Exception {
        JsonFactory factory = new JsonFactory();
        String json = "{\"name\":\"John\", \"age\":30}";
        char[] chars = json.toCharArray();
        JsonParser parser = factory.createParser(ObjectReadContext.empty(), chars);
        assertNotNull(parser);
        parser.close();
    }

    @Test
    public void testCreateGeneratorFromWriter() throws Exception {
        JsonFactory factory = new JsonFactory();
        StringWriter writer = new StringWriter();
        JsonGenerator generator = factory.createGenerator(ObjectWriteContext.empty(), writer);
        assertNotNull(generator);
        generator.writeStartObject();
        generator.writeStringField("name", "John");
        generator.writeNumberField("age", 30);
        generator.writeEndObject();
        generator.close();
        assertEquals("{\"name\":\"John\",\"age\":30}", writer.toString());
    }

    @Test
    public void testCreateGeneratorFromOutputStream() throws Exception {
        JsonFactory factory = new JsonFactory();
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        JsonGenerator generator = factory.createGenerator(ObjectWriteContext.empty(), output, JsonEncoding.UTF8);
        assertNotNull(generator);
        generator.writeStartObject();
        generator.writeStringField("name", "John");
        generator.writeNumberField("age", 30);
        generator.writeEndObject();
        generator.close();
        assertEquals("{\"name\":\"John\",\"age\":30}", output.toString("UTF-8"));
    }

    @Test
    public void testCharacterEscapes() {
        JsonFactory factory = new JsonFactory();
        assertNull(factory.getCharacterEscapes());

        CharacterEscapes escapes = CharacterEscapes.standardAsciiEscapesForJSON();
        JsonFactory customFactory = JsonFactory.builder()
                .characterEscapes(escapes)
                .build();
        assertEquals(escapes, customFactory.getCharacterEscapes());
    }

    @Test
    public void testRootValueSeparator() {
        JsonFactory factory = new JsonFactory();
        assertEquals(JsonFactory.DEFAULT_ROOT_VALUE_SEPARATOR.getValue(), factory.getRootValueSeparator());

        String customSeparator = " : ";
        JsonFactory customFactory = JsonFactory.builder()
                .rootValueSeparator(customSeparator)
                .build();
        assertEquals(customSeparator, customFactory.getRootValueSeparator());
    }

    @Test
    public void testQuoteChar() {
        JsonFactory factory = new JsonFactory();
        assertEquals(JsonFactory.DEFAULT_QUOTE_CHAR, factory._quoteChar);

        char customQuote = '\'';
        JsonFactory customFactory = JsonFactory.builder()
                .quoteChar(customQuote)
                .build();
        assertEquals(customQuote, customFactory._quoteChar);
    }

    @Test
    public void testConstructNameMatcher() {
        JsonFactory factory = new JsonFactory();
        List<Named> names = new ArrayList<>();
        names.add(Named.fromString("name"));
        names.add(Named.fromString("age"));
        BinaryNameMatcher matcher = factory.constructNameMatcher(names, false);
        assertNotNull(matcher);
        assertEquals(2, matcher.nameLookup().length);
    }

    @Test
    public void testConstructCINameMatcher() {
        JsonFactory factory = new JsonFactory();
        List<Named> names = new ArrayList<>();
        names.add(Named.fromString("Name"));
        names.add(Named.fromString("Age"));
        BinaryNameMatcher matcher = factory.constructCINameMatcher(names, false, Locale.ENGLISH);
        assertNotNull(matcher);
        assertEquals(2, matcher.nameLookup().length);
    }

    @Test
    public void testNonBlockingParsers() {
        JsonFactory factory = new JsonFactory();
        assertTrue(factory.canParseAsync());

        JsonParser byteArrayParser = factory.createNonBlockingByteArrayParser(ObjectReadContext.empty());
        assertNotNull(byteArrayParser);
        byteArrayParser.close();

        JsonParser byteBufferParser = factory.createNonBlockingByteBufferParser(ObjectReadContext.empty());
        assertNotNull(byteBufferParser);
        byteBufferParser.close();
    }

    @Test
    public void testVersion() {
        JsonFactory factory = new JsonFactory();
        assertNotNull(factory.version());
    }

    @Test
    public void testSerialization() throws Exception {
        JsonFactory original = new JsonFactory();
        JsonFactory deserialized = (JsonFactory) original.readResolve();
        assertNotNull(deserialized);
        assertEquals(original.getFormatName(), deserialized.getFormatName());
        assertEquals(original.getFormatReadFeatureType(), deserialized.getFormatReadFeatureType());
        assertEquals(original.getFormatWriteFeatureType(), deserialized.getFormatWriteFeatureType());
    }
}

