import tools.jackson.core.util.ByteArrayBuilder;
import tools.jackson.core.util.TextBuffer;

public class ReaderBasedJsonParserTest {

    private ReaderBasedJsonParser parser;

    private IOContext ioContext;

    private CharsToNameCanonicalizer symbols;

    private TextBuffer textBuffer;

    private ByteArrayBuilder byteArrayBuilder;

    public void setUp() {
        ioContext = new IOContext(StreamReadConstraints.defaults(), null, null, null, null, false, null);
        symbols = new CharsToNameCanonicalizer(StreamReadConstraints.defaults(), 0, 0);
        textBuffer = new TextBuffer(null);
        byteArrayBuilder = new ByteArrayBuilder();
    }

