    public void testReleaseBuffered() throws JacksonException, IOException {
        String jsonString = "{\"name\":\"John\"";
        char[] inputBuffer = jsonString.toCharArray();
        parser = new ReaderBasedJsonParser(null, ioContext, 0, 0, null, symbols, inputBuffer, 0, inputBuffer.length, true);

        Writer writer = new StringWriter();
