package tools.jackson.core.json;

import java.io.IOException;
import java.io.OutputStream;
import java.io.Writer;

import tools.jackson.core.Base64Variant;
import tools.jackson.core.JacksonException;
import tools.jackson.core.JsonParser;
import tools.jackson.core.JsonToken;
import tools.jackson.core.StreamReadFeature;
import tools.jackson.core.StreamReadConstraints;
import tools.jackson.core.StreamReadException;
import tools.jackson.core.exc.JacksonIOException;
import tools.jackson.core.io.IOContext;
import tools.jackson.core.sym.CharsToNameCanonicalizer;
import tools.jackson.core.util.ByteArrayBuilder;
import tools.jackson.core.util.TextBuffer;

public class ReaderBasedJsonParserTest {

    private ReaderBasedJsonParser parser;

    private IOContext ioContext;

    private CharsToNameCanonicalizer symbols;

    private TextBuffer textBuffer;

    private ByteArrayBuilder byteArrayBuilder;

    public void setUp() {
        ioContext = new IOContext(StreamReadConstraints.defaults(), null, null, null, null, false, null);
        symbols = new CharsToNameCanonicalizer(StreamReadConstraints.defaults(), 0, 0);
        textBuffer = new TextBuffer(null);
        byteArrayBuilder = new ByteArrayBuilder();
    }

    public void testGetString() throws JacksonException {
        String testString = "test string";
        char[] inputBuffer = testString.toCharArray();
        parser = new ReaderBasedJsonParser(null, ioContext, 0, 0, null, symbols, inputBuffer, 0, inputBuffer.length, true);

        parser.nextToken();
        String result = parser.getString();
        assertEquals(testString, result);
    }

    public void testGetStringWithIncompleteToken() throws JacksonException {
        String testString = "test string";
        char[] inputBuffer = testString.toCharArray();
        parser = new ReaderBasedJsonParser(null, ioContext, 0, 0, null, symbols, inputBuffer, 0, inputBuffer.length, true);

        parser.nextToken();
        parser._tokenIncomplete = true;
        String result = parser.getString();
        assertEquals(testString, result);
        assertFalse(parser._tokenIncomplete);
    }

    public void testGetStringCharacters() throws JacksonException {
        String testString = "test string";
        char[] inputBuffer = testString.toCharArray();
        parser = new ReaderBasedJsonParser(null, ioContext, 0, 0, null, symbols, inputBuffer, 0, inputBuffer.length, true);

        parser.nextToken();
        char[] result = parser.getStringCharacters();
        assertArrayEquals(testString.toCharArray(), result);
    }

    public void testGetStringLength() throws JacksonException {
        String testString = "test string";
        char[] inputBuffer = testString.toCharArray();
        parser = new ReaderBasedJsonParser(null, ioContext, 0, 0, null, symbols, inputBuffer, 0, inputBuffer.length, true);

        parser.nextToken();
        int result = parser.getStringLength();
        assertEquals(testString.length(), result);
    }

    public void testGetStringOffset() throws JacksonException {
        String testString = "test string";
        char[] inputBuffer = testString.toCharArray();
        parser = new ReaderBasedJsonParser(null, ioContext, 0, 0, null, symbols, inputBuffer, 0, inputBuffer.length, true);

        parser.nextToken();
        int result = parser.getStringOffset();
        assertEquals(0, result);
    }

    public void testGetBinaryValue() throws JacksonException {
        String base64String = "SGVsbG8gV29ybGQ=";
        byte[] expectedBytes = "Hello World".getBytes();
        char[] inputBuffer = base64String.toCharArray();
        parser = new ReaderBasedJsonParser(null, ioContext, 0, 0, null, symbols, inputBuffer, 0, inputBuffer.length, true);

        parser.nextToken();
        byte[] result = parser.getBinaryValue(Base64Variants.getDefaultVariant());
        assertArrayEquals(expectedBytes, result);
    }

    public void testReadBinaryValue() throws JacksonException, IOException {
        String base64String = "SGVsbG8gV29ybGQ=";
        byte[] expectedBytes = "Hello World".getBytes();
        char[] inputBuffer = base64String.toCharArray();
        parser = new ReaderBasedJsonParser(null, ioContext, 0, 0, null, symbols, inputBuffer, 0, inputBuffer.length, true);

        parser.nextToken();
        OutputStream outputStream = new ByteArrayOutputStream();
        int result = parser.readBinaryValue(Base64Variants.getDefaultVariant(), outputStream);
        byte[] actualBytes = ((ByteArrayOutputStream) outputStream).toByteArray();
        assertArrayEquals(expectedBytes, actualBytes);
        assertEquals(expectedBytes.length, result);
    }

    public void testNextToken() throws JacksonException {
        String jsonString = "{\"name\":\"John\", \"age\":30}";
        char[] inputBuffer = jsonString.toCharArray();
        parser = new ReaderBasedJsonParser(null, ioContext, 0, 0, null, symbols, inputBuffer, 0, inputBuffer.length, true);

        JsonToken token = parser.nextToken();
        assertEquals(JsonToken.START_OBJECT, token);

        token = parser.nextToken();
        assertEquals(JsonToken.PROPERTY_NAME, token);

        token = parser.nextToken();
        assertEquals(JsonToken.VALUE_STRING, token);

        token = parser.nextToken();
        assertEquals(JsonToken.PROPERTY_NAME, token);

        token = parser.nextToken();
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);

        token = parser.nextToken();
        assertEquals(JsonToken.END_OBJECT, token);
    }

