    private static class TestDataInput implements DataInput {
        private byte[] data;
        private int position;

        public TestDataInput(byte[] data) {
            this.data = data;
            this.position = 0;
        }

        @Override
        public void readFully(byte[] b) throws IOException {
            System.arraycopy(data, position, b, 0, b.length);
            position += b.length;
        }

        @Override
        public void readFully(byte[] b, int off, int len) throws IOException {
            System.arraycopy(data, position, b, off, len);
            position += len;
        }

        @Override
        public int skipBytes(int n) throws IOException {
            position += n;
            return n;
        }

        @Override
        public boolean readBoolean() throws IOException {
            return data[position++] != 0;
        }

        @Override
        public byte readByte() throws IOException {
            return data[position++];
        }

        @Override
        public int readUnsignedByte() throws IOException {
            return data[position++] & 0xFF;
        }

        @Override
        public short readShort() throws IOException {
            return (short) ((data[position++] & 0xFF) | ((data[position++] & 0xFF) << 8));
        }

        @Override
        public int readUnsignedShort() throws IOException {
            return (data[position++] & 0xFF) | ((data[position++] & 0xFF) << 8);
        }

        @Override
        public char readChar() throws IOException {
            return (char) ((data[position++] & 0xFF) | ((data[position++] & 0xFF) << 8));
        }

        @Override
        public int readInt() throws IOException {
            return (data[position++] & 0xFF) | ((data[position++] & 0xFF) << 8) |
                   ((data[position++] & 0xFF) << 16) | ((data[position++] & 0xFF) << 24);
        }

        @Override
        public long readLong() throws IOException {
            return ((long) (data[position++] & 0xFF)) | ((long) (data[position++] & 0xFF) << 8) |
                   ((long) (data[position++] & 0xFF) << 16) | ((long) (data[position++] & 0xFF) << 24) |
                   ((long) (data[position++] & 0xFF) << 32) | ((long) (data[position++] & 0xFF) << 40) |
                   ((long) (data[position++] & 0xFF) << 48) | ((long) (data[position++] & 0xFF) << 56);
        }

        @Override
        public float readFloat() throws IOException {
            return Float.intBitsToFloat(readInt());
        }

        @Override
        public double readDouble() throws IOException {
            return Double.longBitsToDouble(readLong());
        }

        @Override
        public String readUTF() throws IOException {
            return new String(data, position, data.length - position);
        }
    }
}

