package tools.jackson.core.json;

import org.junit.Test;
import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import java.io.Writer;

import tools.jackson.core.Base64Variant;
import tools.jackson.core.JsonParser;
import tools.jackson.core.JsonToken;
import tools.jackson.core.ObjectReadContext;
import tools.jackson.core.StreamReadFeature;
import tools.jackson.core.StreamReadConstraints;
import tools.jackson.core.StreamWriteFeature;
import tools.jackson.core.exc.JacksonException;
import tools.jackson.core.exc.StreamReadException;
import tools.jackson.core.io.IOContext;
import tools.jackson.core.sym.ByteQuadsCanonicalizer;
import tools.jackson.core.util.BufferRecycler;

public class UTF8StreamJsonParserTest {

    private static final String TEST_STRING = "{\"name\":\"John\", \"age\":30, \"city\":\"New York\"}";
    private static final String TEST_STRING_WITH_BASE64 = "{\"data\":\"SGVsbG8gd29ybGQh\"}";
    private static final String TEST_STRING_WITH_SINGLE_QUOTE = "{\"name\":\"O'Reilly\"}";

    @Test
    public void testGetString() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertEquals("John", parser.getString());
        parser.nextToken();
        parser.nextToken();
        assertEquals(30, parser.getIntValue());
        parser.nextToken();
        parser.nextToken();
        assertEquals("New York", parser.getString());
    }

    @Test
    public void testGetStringWithSingleQuote() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING_WITH_SINGLE_QUOTE);
        parser.nextToken();
        assertEquals("O'Reilly", parser.getString());
    }

    @Test
    public void testGetStringWithBase64() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING_WITH_BASE64);
        parser.nextToken();
        parser.nextToken();
        byte[] decodedBytes = parser.getBinaryValue(Base64Variants.getDefaultVariant());
        assertArrayEquals("Hello world!".getBytes(), decodedBytes);
    }

    @Test
    public void testGetStringCharacters() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        char[] chars = parser.getStringCharacters();
        assertEquals("John", new String(chars, 0, parser.getStringLength()));
    }

    @Test
    public void testGetStringLength() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertEquals(4, parser.getStringLength());
    }

    @Test
    public void testGetStringOffset() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertEquals(0, parser.getStringOffset());
    }

    @Test
    public void testGetValueAsString() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertEquals("John", parser.getValueAsString());
    }

    @Test
    public void testGetValueAsInt() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
        assertEquals(30, parser.getValueAsInt());
    }

    @Test
    public void testGetValueAsLong() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
        assertEquals(30L, parser.getValueAsLong());
    }

    @Test
    public void testGetValueAsDouble() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
        assertEquals(30.0, parser.getValueAsDouble(), 0.0001);
    }

    @Test
    public void testGetValueAsBoolean() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertFalse(parser.getValueAsBoolean());
    }

    @Test
    public void testNextToken() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextName() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertEquals("name", parser.nextName());
        assertEquals("age", parser.nextName());
        assertEquals("city", parser.nextName());
        assertNull(parser.nextName());
    }

    @Test
    public void testNextStringValue() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertEquals("John", parser.nextStringValue());
        parser.nextToken();
        assertEquals("New York", parser.nextStringValue());
        assertNull(parser.nextStringValue());
    }

    @Test
    public void testNextIntValue() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertEquals(30, parser.nextIntValue(0));
        assertEquals(0, parser.nextIntValue(0));
    }

    @Test
    public void testNextLongValue() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertEquals(30L, parser.nextLongValue(0L));
        assertEquals(0L, parser.nextLongValue(0L));
    }

    @Test
    public void testNextBooleanValue() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertNull(parser.nextBooleanValue());
    }

    @Test
    public void testReadBinaryValue() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING_WITH_BASE64);
        parser.nextToken();
        parser.nextToken();
        Writer writer = new StringWriter();
        int bytesRead = parser.readBinaryValue(writer);
        assertEquals("Hello world!".length(), bytesRead);
        assertEquals("Hello world!", writer.toString());
    }

    @Test(expected = StreamReadException.class)
    public void testInvalidJson() throws JacksonException {
        String invalidJson = "{\"name\":\"John\", \"age\":30, \"city\":\"New York\"";
        JsonParser parser = createParser(invalidJson);
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
    }

    private JsonParser createParser(String content) throws JacksonException {
        ObjectReadContext readCtxt = ObjectReadContext.empty();
        IOContext ctxt = new IOContext(
            StreamReadConstraints.defaults(),
            StreamWriteFeature.collectDefaults(),
            BufferRecycler.getDefaultInstance(),
            null,
            false,
            null
        );
        return new UTF8StreamJsonParser(
            readCtxt,
            ctxt,
            StreamReadFeature.collectDefaults(),
            StreamWriteFeature.collectDefaults(),
            new StringReader(content),
            new ByteQuadsCanonicalizer(128, 2),
            null,
            0,
            0,
            0,
            false
        );
    }
}

