        JsonParser parser = createParser(TEST_STRING);
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextName() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertEquals("name", parser.nextName());
        assertEquals("age", parser.nextName());
        assertEquals("city", parser.nextName());
        assertNull(parser.nextName());
    }

    @Test
    public void testNextStringValue() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertEquals("John", parser.nextStringValue());
        parser.nextToken();
        assertEquals("New York", parser.nextStringValue());
        assertNull(parser.nextStringValue());
    }

    @Test
    public void testNextIntValue() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertEquals(30, parser.nextIntValue(0));
        assertEquals(0, parser.nextIntValue(0));
    }

    @Test
    public void testNextLongValue() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertEquals(30L, parser.nextLongValue(0L));
        assertEquals(0L, parser.nextLongValue(0L));
    }

    @Test
    public void testNextBooleanValue() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING);
        parser.nextToken();
        assertNull(parser.nextBooleanValue());
    }

    @Test
    public void testReadBinaryValue() throws JacksonException {
        JsonParser parser = createParser(TEST_STRING_WITH_BASE64);
        parser.nextToken();
        parser.nextToken();
        Writer writer = new StringWriter();
        int bytesRead = parser.readBinaryValue(writer);
        assertEquals("Hello world!".length(), bytesRead);
        assertEquals("Hello world!", writer.toString());
    }

    @Test(expected = StreamReadException.class)
    public void testInvalidJson() throws JacksonException {
        String invalidJson = "{\"name\":\"John\", \"age\":30, \"city\":\"New York\"";
        JsonParser parser = createParser(invalidJson);
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
        parser.nextToken();
    }

    private JsonParser createParser(String content) throws JacksonException {
        ObjectReadContext readCtxt = ObjectReadContext.empty();
        IOContext ctxt = new IOContext(
            StreamReadConstraints.defaults(),
            StreamWriteFeature.collectDefaults(),
            BufferRecycler.getDefaultInstance(),
            null,
            false,
            null
        );
        return new UTF8StreamJsonParser(
            readCtxt,
            ctxt,
            StreamReadFeature.collectDefaults(),
            StreamWriteFeature.collectDefaults(),
            new StringReader(content),
            new ByteQuadsCanonicalizer(128, 2),
            null,
            0,
            0,
            0,
            false
        );
    }
}

