    @Before
    public void setUp() {
        readContext = ObjectReadContext.empty();
        ioContext = new IOContext(constraints, null, null, null, null, false, null);
        sym = new ByteQuadsCanonicalizer(1024, 0);
        constraints = StreamReadConstraints.defaults();
    }

    @Test
    public void testConstructor() {
