        NonBlockingByteArrayJsonParser parser = new NonBlockingByteArrayJsonParser(
            readContext, ioContext, 0, 0, sym);
        parser._inputPtr = 5;
        parser._inputEnd = 10;
        byte[] data = new byte[10];
        Arrays.fill(data, (byte) 0x01);

        try {
            parser.feedInput(data, 0, 10);
            fail("Should throw exception when there are undecoded bytes");
