            readContext, ioContext, 0, 0, sym);
        assertEquals(readContext, parser.objectReadContext());
    }

    @Test
    public void testNonBlockingInputFeeder() {
        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);
        assertEquals(parser, parser.nonBlockingInputFeeder());
    }

    @Test
    public void testFeedInputWithEmptyBuffer() throws JacksonException {
        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);
        ByteBuffer buffer = ByteBuffer.wrap(new byte[0]);
        parser.feedInput(buffer);
    }

    @Test
    public void testFeedInputWithValidData() throws JacksonException {
        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);
        byte[] data = "{\"test\":\"value\"}".getBytes();
        ByteBuffer buffer = ByteBuffer.wrap(data);
        parser.feedInput(buffer);
    }

    @Test(expected = JacksonException.class)
    public void testFeedInputWithInvalidData() throws JacksonException {
        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);
        byte[] data = "invalid".getBytes();
        ByteBuffer buffer = ByteBuffer.wrap(data);
        parser.feedInput(buffer);
    }

    @Test(expected = JacksonException.class)
    public void testFeedInputWithEndBeforeStart() throws JacksonException {
        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);
        ByteBuffer buffer = ByteBuffer.wrap(new byte[10]);
        buffer.position(5);
        buffer.limit(3);
        parser.feedInput(buffer);
    }

    @Test(expected = JacksonException.class)
    public void testFeedInputAfterEndOfInput() throws JacksonException {
        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);
        parser.endOfInput();
        ByteBuffer buffer = ByteBuffer.wrap(new byte[10]);
        parser.feedInput(buffer);
    }

    @Test
    public void testReleaseBuffered() throws JacksonException {
        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);
        byte[] data = "test data".getBytes();
        ByteBuffer buffer = ByteBuffer.wrap(data);
        parser.feedInput(buffer);

        ByteArrayOutputStream output = new ByteArrayOutputStream();
        int released = parser.releaseBuffered(output);
        assertEquals(data.length, released);
        assertEquals("test data", output.toString());
    }

    @Test
    public void testReleaseBufferedWithEmptyBuffer() throws JacksonException {
        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);
        ByteBuffer buffer = ByteBuffer.wrap(new byte[0]);
        parser.feedInput(buffer);

        ByteArrayOutputStream output = new ByteArrayOutputStream();
        int released = parser.releaseBuffered(output);
        assertEquals(0, released);
        assertEquals("", output.toString());
    }

    @Test
    public void testGetNextSignedByteFromBuffer() throws JacksonException {
        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);
        byte[] data = {1, 2, 3, 4, 5};
        ByteBuffer buffer = ByteBuffer.wrap(data);
        parser.feedInput(buffer);

        assertEquals(1, parser.getNextSignedByteFromBuffer());
        assertEquals(2, parser.getNextSignedByteFromBuffer());
        assertEquals(3, parser.getNextSignedByteFromBuffer());
    }

