        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);
        byte[] data = {-1, -2, -3, -4, -5};
        ByteBuffer buffer = ByteBuffer.wrap(data);
        parser.feedInput(buffer);

        assertEquals(255, parser.getNextUnsignedByteFromBuffer());
        assertEquals(254, parser.getNextUnsignedByteFromBuffer());
        assertEquals(253, parser.getNextUnsignedByteFromBuffer());
    }

    @Test
    public void testGetByteFromBuffer() throws JacksonException {
        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);
        byte[] data = {10, 20, 30, 40, 50};
        ByteBuffer buffer = ByteBuffer.wrap(data);
        parser.feedInput(buffer);

        assertEquals(10, parser.getByteFromBuffer(0));
        assertEquals(20, parser.getByteFromBuffer(1));
        assertEquals(30, parser.getByteFromBuffer(2));
    }

    @Test(expected = JacksonException.class)
    public void testFeedInputWithUndecodedBytes() throws JacksonException {
        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);
        byte[] data = "test".getBytes();
        ByteBuffer buffer = ByteBuffer.wrap(data);
        parser.feedInput(buffer);

        // Simulate undecoded bytes by not consuming all data
        parser.getNextUnsignedByteFromBuffer();

        // Try to feed more data
        byte[] moreData = "more".getBytes();
        ByteBuffer moreBuffer = ByteBuffer.wrap(moreData);
        parser.feedInput(moreBuffer);
    }

    @Test
    public void testFeedInputWithLargeData() throws JacksonException {
        NonBlockingByteBufferJsonParser parser = new NonBlockingByteBufferJsonParser(
            readContext, ioContext, 0, 0, sym);

        // Create a large buffer
        byte[] largeData = new byte[10000];
        Arrays.fill(largeData, (byte) 'a');
        ByteBuffer buffer = ByteBuffer.wrap(largeData);
