public class BinaryNameMatcherTest {

    @Test
    public void testAddNameWithShortString() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("test"));
        assertEquals(1, matcher.size());
    }

    @Test
    public void testAddNameWithLongString() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("aVeryLongStringThatExceedsTheInitialBufferSize"));
        assertEquals(1, matcher.size());
    }

    @Test
    public void testMatchByQuadWithSingleQuad() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("test"));
        int index = matcher.addName("test");
        int quad = matcher._quads("test")[0];
        assertEquals(index, matcher.matchByQuad(quad));
    }

    @Test
    public void testMatchByQuadWithTwoQuads() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("longerTest"));
        int index = matcher.addName("longerTest");
        int[] quads = matcher._quads("longerTest");
        assertEquals(index, matcher.matchByQuad(quads[0], quads[1]));
    }

    @Test
    public void testMatchByQuadWithThreeQuads() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("evenLongerTestString"));
        int index = matcher.addName("evenLongerTestString");
        int[] quads = matcher._quads("evenLongerTestString");
        assertEquals(index, matcher.matchByQuad(quads[0], quads[1], quads[2]));
    }

    @Test
    public void testMatchByQuadWithArray() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("veryLongStringThatRequiresMultipleQuads"));
        int index = matcher.addName("veryLongStringThatRequiresMultipleQuads");
        int[] quads = matcher._quads("veryLongStringThatRequiresMultipleQuads");
        assertEquals(index, matcher.matchByQuad(quads, quads.length));
    }

    @Test
    public void testMatchByQuadWithNonExistentName() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("existingName"));
        int[] quads = matcher._quads("nonExistentName");
        assertEquals(-1, matcher.matchByQuad(quads[0]));
    }

    @Test
    public void testMatchByQuadWithEmptyName() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("existingName"));
        assertEquals(-1, matcher.matchByQuad(0));
    }

    @Test
    public void testSize() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("name1", "name2", "name3"));
        assertEquals(3, matcher.size());
    }

    @Test
    public void testBucketCount() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("name1", "name2", "name3"));
        assertTrue(matcher.bucketCount() > 0);
    }

    @Test
    public void testPrimaryQuadCount() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("name1", "name2", "name3"));
        assertEquals(3, matcher.primaryQuadCount());
    }

    @Test
    public void testSecondaryQuadCount() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("name1", "name2", "name3"));
        assertEquals(0, matcher.secondaryQuadCount());
    }

    @Test
    public void testTertiaryQuadCount() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("name1", "name2", "name3"));
        assertEquals(0, matcher.tertiaryQuadCount());
    }

    @Test
    public void testSpilloverQuadCount() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("name1", "name2", "name3"));
        assertEquals(0, matcher.spilloverQuadCount());
    }

    @Test
    public void testTotalCount() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("name1", "name2", "name3"));
        assertEquals(3, matcher.totalCount());
    }

    @Test
    public void testToString() {
        BinaryNameMatcher matcher = BinaryNameMatcher.construct(Arrays.asList("name1", "name2", "name3"));
        String toString = matcher.toString();
        assertTrue(toString.contains("size=3"));
        assertTrue(toString.contains("hashSize="));
    }

    @Test
    public void testCalcTertiaryShift() {
        assertEquals(4, BinaryNameMatcher._calcTertiaryShift(32));
        assertEquals(5, BinaryNameMatcher._calcTertiaryShift(64));
        assertEquals(6, BinaryNameMatcher._calcTertiaryShift(128));
        assertEquals(7, BinaryNameMatcher._calcTertiaryShift(256));
    }

    @Test
    public void testQuadsConversion() {
        String name = "test";
        int[] quads = BinaryNameMatcher._quads(name);
        assertEquals(1, quads.length);
        assertEquals(0x00000074, quads[0]); // 't' in UTF-8

        name = "longer";
        quads = BinaryNameMatcher._quads(name);
        assertEquals(2, quads.length);
        assertEquals(0x0000006C, quads[0]); // 'l' in UTF-8
        assertEquals(0x006F6E67, quads[1]); // 'o', 'n', 'g', 'e' in UTF-8
    }

    @Test
    public void testDecodeFull() {
        byte[] bytes = {0x00, 0x00, 0x00, 0x74}; // 't' in UTF-8
        assertEquals(0x00000074, BinaryNameMatcher._decodeFull(bytes, 0));
    }

    @Test
    public void testDecodeLast() {
        byte[] bytes = {0x74}; // 't' in UTF-8
        assertEquals(0x00000074, BinaryNameMatcher._decodeLast(bytes, 0, 1));

        bytes = new byte[]{0x00, 0x00, 0x00, 0x74}; // 't' in UTF-8
        assertEquals(0x00000074, BinaryNameMatcher._decodeLast(bytes, 0, 4));
    }

    @Test
    public void testLengthAndIndex() {
        BinaryNameMatcher matcher = new BinaryNameMatcher(null, new String[0], 10);
        assertEquals(0x00000001, matcher._lengthAndIndex(1));
        assertEquals(1, matcher.size());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testLengthAndIndexWithTooLongName() {
        BinaryNameMatcher matcher = new BinaryNameMatcher(null, new String[0], 10);
        matcher._lengthAndIndex(BinaryNameMatcher.MAX_LENGTH_IN_QUADS + 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testLengthAndIndexWithTooManyEntries() {
        BinaryNameMatcher matcher = new BinaryNameMatcher(null, new String[0], 10);
        for (int i = 0; i < BinaryNameMatcher.MAX_ENTRIES; i++) {
            matcher._lengthAndIndex(1);
        }
        matcher._lengthAndIndex(1);
    }

    @Test
    public void testSpilloverStart() {
        BinaryNameMatcher matcher = new BinaryNameMatcher(null, new String[0], 10);
        assertEquals(70, matcher._spilloverStart());
    }
}

