import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import tools.jackson.core.exc.StreamConstraintsException;
import tools.jackson.core.util.InternCache;

@RunWith(MockitoJUnitRunner.class)
public class ByteQuadsCanonicalizerTest {

    @Test
    public void testCreateRoot() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        assertNotNull(root);
        assertEquals(64, root.bucketCount());
        assertEquals(0, root.size());
    }

    @Test
    public void testCreateRootWithSeed() {
        int seed = 12345;
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(seed);
        assertNotNull(root);
        assertEquals(seed, root.hashSeed());
    }

    @Test
    public void testMakeChild() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        ByteQuadsCanonicalizer child = root.makeChild(0);
        assertNotNull(child);
        assertEquals(root.bucketCount(), child.bucketCount());
        assertEquals(0, child.size());
    }

    @Test
    public void testMakeChildOrPlaceholder() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        // Test with canonicalization enabled
        ByteQuadsCanonicalizer child = root.makeChildOrPlaceholder(1);
        assertNotNull(child);
        assertEquals(root.bucketCount(), child.bucketCount());
        assertEquals(0, child.size());

        // Test with canonicalization disabled
        child = root.makeChildOrPlaceholder(0);
        assertNotNull(child);
        assertEquals(root.bucketCount(), child.bucketCount());
        assertEquals(0, child.size());
    }

    @Test
    public void testAddName() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        ByteQuadsCanonicalizer child = root.makeChild(0);

        String name = "test";
        int q1 = 0x12345678;
        String result = child.addName(name, q1);

        assertEquals(name, result);
        assertEquals(1, child.size());
    }

    @Test
    public void testAddNameWithInterning() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        ByteQuadsCanonicalizer child = root.makeChild(1); // Enable INTERN_PROPERTY_NAMES

        String name = "test";
        int q1 = 0x12345678;
        String result = child.addName(name, q1);

        assertEquals(name.intern(), result);
        assertEquals(1, child.size());
    }

    @Test
    public void testFindName() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        ByteQuadsCanonicalizer child = root.makeChild(0);

        String name = "test";
        int q1 = 0x12345678;
        child.addName(name, q1);

        String found = child.findName(q1);
        assertEquals(name, found);
    }

    @Test
    public void testFindNameNotFound() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        ByteQuadsCanonicalizer child = root.makeChild(0);

        int q1 = 0x12345678;
        String found = child.findName(q1);
        assertNull(found);
    }

    @Test
    public void testRelease() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        ByteQuadsCanonicalizer child = root.makeChild(0);

        String name = "test";
        int q1 = 0x12345678;
        child.addName(name, q1);

        assertEquals(1, child.size());
        child.release();
        assertEquals(1, root.size());
    }

    @Test
    public void testSize() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        assertEquals(0, root.size());
    }

    @Test
    public void testIsCanonicalizing() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        assertFalse(root.isCanonicalizing());

        ByteQuadsCanonicalizer child = root.makeChild(0);
        assertTrue(child.isCanonicalizing());
    }

    @Test
    public void testWillInternStrings() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        assertFalse(root.willInternStrings());

        ByteQuadsCanonicalizer child = root.makeChild(1); // Enable INTERN_PROPERTY_NAMES
        assertTrue(child.willInternStrings());
    }

    @Test
    public void testCalcHash() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        int q1 = 0x12345678;
        int hash = root.calcHash(q1);
        assertNotEquals(0, hash);
    }

    @Test
    public void testCalcHashWithSeed() {
        int seed = 12345;
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(seed);
        int q1 = 0x12345678;
        int hash = root.calcHash(q1);
        assertNotEquals(0, hash);
    }

    @Test
    public void testCalcHashMultiQuad() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        int[] quads = {0x12345678, 0x87654321, 0x11223344};
        int hash = root.calcHash(quads, quads.length);
        assertNotEquals(0, hash);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCalcHashTooShort() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        int[] quads = {0x12345678, 0x87654321};
        root.calcHash(quads, quads.length);
    }

    @Test
    public void testToString() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        String str = root.toString();
        assertNotNull(str);
        assertTrue(str.contains("size=0"));
        assertTrue(str.contains("hashSize=64"));
    }
}

