        builder.appendThreeBytes(0x123456);
        byte[] result = builder.toByteArray();
        assertArrayEquals(new byte[]{(byte)0x12, (byte)0x34, (byte)0x56}, result);
    }

    @Test
    public void testAppendFourBytes() {
        ByteArrayBuilder builder = new ByteArrayBuilder();
        builder.appendFourBytes(0x12345678);
        byte[] result = builder.toByteArray();
        assertArrayEquals(new byte[]{(byte)0x12, (byte)0x34, (byte)0x56, (byte)0x78}, result);
    }

    @Test
    public void testToByteArray() {
        ByteArrayBuilder builder = new ByteArrayBuilder();
        byte[] result = builder.toByteArray();
        assertArrayEquals(ByteArrayBuilder.NO_BYTES, result);

        builder.append(1);
        result = builder.toByteArray();
        assertArrayEquals(new byte[]{1}, result);
    }

    @Test
    public void testGetClearAndRelease() {
        ByteArrayBuilder builder = new ByteArrayBuilder();
        builder.append(1);
        builder.append(2);
        byte[] result = builder.getClearAndRelease();
        assertArrayEquals(new byte[]{1, 2}, result);
        assertEquals(0, builder.size());
    }

    @Test
    public void testOutputStreamMethods() throws IOException {
        ByteArrayBuilder builder = new ByteArrayBuilder();
        builder.write(1);
        builder.write(new byte[]{2, 3}, 0, 2);
        byte[] result = builder.toByteArray();
        assertArrayEquals(new byte[]{1, 2, 3}, result);
    }

    @Test
    public void testBufferRecyclerMethods() {
        BufferRecycler recycler = new BufferRecycler();
        ByteArrayBuilder builder = new ByteArrayBuilder(recycler);
        assertEquals(recycler, builder.bufferRecycler());
    }

    @Test
    public void testManualOutputMethods() {
        ByteArrayBuilder builder = new ByteArrayBuilder();
        byte[] segment = builder.resetAndGetFirstSegment();
        segment[0] = 1;
        segment[1] = 2;
        builder.setCurrentSegmentLength(2);
        byte[] result = builder.completeAndCoalesce(2);
        assertArrayEquals(new byte[]{1, 2}, result);
    }

    @Test
    public void testLargeDataHandling() {
        ByteArrayBuilder builder = new ByteArrayBuilder();
        for (int i = 0; i < 10000; i++) {
            builder.append(i);
        }
        byte[] result = builder.toByteArray();
        assertEquals(10000, result.length);
    }

    @Test(expected = IllegalStateException.class)
    public void testMaxSizeExceeded() {
        ByteArrayBuilder builder = new ByteArrayBuilder();
        // Fill up to near the max size
        for (int i = 0; i < Integer.MAX_VALUE - 1000; i++) {
            builder.append(i);
        }
        // This should trigger the max size exception
        builder.append(1);
    }
}

