public class DefaultIndenterTest {

    @Test
    public void testDefaultConstructor() {
        DefaultIndenter indenter = new DefaultIndenter();
        assertEquals("  ", indenter.getIndent());
        assertEquals(DefaultIndenter.SYS_LF, indenter.getEol());
    }

    @Test
    public void testParameterizedConstructor() {
        String indent = ">>>";
        String eol = "\r\n";
        DefaultIndenter indenter = new DefaultIndenter(indent, eol);
        assertEquals(indent, indenter.getIndent());
        assertEquals(eol, indenter.getEol());
    }

    @Test
    public void testWithLinefeed() {
        DefaultIndenter original = new DefaultIndenter("  ", "\n");
        DefaultIndenter newIndenter = original.withLinefeed("\r\n");
        assertEquals("\r\n", newIndenter.getEol());
        assertEquals(original.getIndent(), newIndenter.getIndent());
        assertNotSame(original, newIndenter);
    }

    @Test
    public void testWithIndent() {
        DefaultIndenter original = new DefaultIndenter("  ", "\n");
        DefaultIndenter newIndenter = original.withIndent(">>>");
        assertEquals(">>>", newIndenter.getIndent());
        assertEquals(original.getEol(), newIndenter.getEol());
        assertNotSame(original, newIndenter);
    }

    @Test
