        DefaultIndenter indenter = new DefaultIndenter();
        assertFalse(indenter.isInline());
    }

    @Test
    public void testWriteIndentation() throws JacksonException {
        MockJsonGenerator generator = new MockJsonGenerator();
        DefaultIndenter indenter = new DefaultIndenter("  ", "\n");

        indenter.writeIndentation(generator, 0);
        assertEquals("", generator.getRawOutput());

        indenter.writeIndentation(generator, 1);
        assertEquals("\n  ", generator.getRawOutput());

        indenter.writeIndentation(generator, 2);
        assertEquals("\n  \n    ", generator.getRawOutput());
    }

    @Test
    public void testWriteIndentationWithNegativeLevel() throws JacksonException {
        MockJsonGenerator generator = new MockJsonGenerator();
        DefaultIndenter indenter = new DefaultIndenter("  ", "\n");
        indenter.writeIndentation(generator, -1);
        assertEquals("", generator.getRawOutput());
    }

    @Test
    public void testWriteIndentationWithLargeLevel() throws JacksonException {
        MockJsonGenerator generator = new MockJsonGenerator();
        DefaultIndenter indenter = new DefaultIndenter("  ", "\n");
        indenter.writeIndentation(generator, 100);
        assertTrue(generator.getRawOutput().length() > 0);
    }

    @Test
    public void testSystemLinefeedInstance() {
        DefaultIndenter indenter = DefaultIndenter.SYSTEM_LINEFEED_INSTANCE;
        assertEquals("  ", indenter.getIndent());
        assertEquals(DefaultIndenter.SYS_LF, indenter.getEol());
    }

