        assertNotNull(printer);
        assertEquals(Separators.createDefaultInstance(), printer._separators);
    }

    @Test
    public void testConstructorWithSeparators() {
        Separators customSeparators = new Separators(':', ',', ',');
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter(customSeparators);
        assertNotNull(printer);
        assertEquals(customSeparators, printer._separators);
    }

    @Test
    public void testCopyConstructor() {
        DefaultPrettyPrinter original = new DefaultPrettyPrinter();
        DefaultPrettyPrinter copy = new DefaultPrettyPrinter(original);
        assertNotNull(copy);
        assertEquals(original._arrayIndenter, copy._arrayIndenter);
        assertEquals(original._objectIndenter, copy._objectIndenter);
        assertEquals(original._separators, copy._separators);
    }

    @Test
    public void testCopyConstructorWithSeparators() {
        Separators originalSeparators = new Separators(':', ',', ',');
        DefaultPrettyPrinter original = new DefaultPrettyPrinter(originalSeparators);
        Separators newSeparators = new Separators('=', ',', ',');
        DefaultPrettyPrinter copy = new DefaultPrettyPrinter(original, newSeparators);
        assertNotNull(copy);
        assertEquals(original._arrayIndenter, copy._arrayIndenter);
        assertEquals(original._objectIndenter, copy._objectIndenter);
        assertEquals(newSeparators, copy._separators);
    }

    @Test
    public void testIndentArraysWith() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        printer.indentArraysWith(null);
        assertEquals(DefaultPrettyPrinter.NopIndenter.instance(), printer._arrayIndenter);
    }

    @Test
    public void testIndentObjectsWith() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        printer.indentObjectsWith(null);
        assertEquals(DefaultPrettyPrinter.NopIndenter.instance(), printer._objectIndenter);
    }

    @Test
    public void testWithArrayIndenter() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        DefaultPrettyPrinter newPrinter = printer.withArrayIndenter(DefaultPrettyPrinter.FixedSpaceIndenter.instance());
        assertNotSame(printer, newPrinter);
        assertEquals(DefaultPrettyPrinter.FixedSpaceIndenter.instance(), newPrinter._arrayIndenter);
    }

    @Test
    public void testWithObjectIndenter() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        DefaultPrettyPrinter newPrinter = printer.withObjectIndenter(DefaultPrettyPrinter.FixedSpaceIndenter.instance());
        assertNotSame(printer, newPrinter);
        assertEquals(DefaultPrettyPrinter.FixedSpaceIndenter.instance(), newPrinter._objectIndenter);
    }

    @Test
    public void testWithSeparators() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        Separators newSeparators = new Separators('=', ',', ',');
        DefaultPrettyPrinter newPrinter = printer.withSeparators(newSeparators);
        assertNotSame(printer, newPrinter);
        assertEquals(newSeparators, newPrinter._separators);
    }

    @Test
    public void testCreateInstance() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        DefaultPrettyPrinter instance = printer.createInstance();
        assertNotSame(printer, instance);
        assertEquals(printer._arrayIndenter, instance._arrayIndenter);
        assertEquals(printer._objectIndenter, instance._objectIndenter);
        assertEquals(printer._separators, instance._separators);
    }

    @Test(expected = IllegalStateException.class)
    public void testCreateInstanceWithSubclass() {
        DefaultPrettyPrinter subclassInstance = new DefaultPrettyPrinter() {};
        subclassInstance.createInstance();
    }
}

