package tools.jackson.core.util;

import static org.junit.Assert.*;
import org.junit.Test;
import java.util.concurrent.locks.ReentrantLock;

public class InternCacheTest {

    @Test
    public void testInternWithNewString() {
        InternCache cache = new InternCache(10, 0.8f, 1);
        String input = "testString";
        String result = cache.intern(input);
        assertEquals(input, result);
        assertEquals(1, cache.size());
    }

    @Test
    public void testInternWithCachedString() {
        InternCache cache = new InternCache(10, 0.8f, 1);
        String input = "testString";
        String result1 = cache.intern(input);
        String result2 = cache.intern(input);
        assertSame(result1, result2);
        assertEquals(1, cache.size());
    }

    @Test
    public void testInternWithNullInput() {
        InternCache cache = new InternCache(10, 0.8f, 1);
        try {
            cache.intern(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Expected
        }
    }

    @Test
    public void testInternWithMaxEntries() {
        InternCache cache = new InternCache(2, 0.8f, 1);
        String input1 = "string1";
        String input2 = "string2";
        String input3 = "string3";

        cache.intern(input1);
        cache.intern(input2);
        cache.intern(input3);

        assertEquals(2, cache.size()); // Should have cleared some entries
    }

    @Test
    public void testInternWithConcurrentAccess() {
        InternCache cache = InternCache.instance;
        String input = "concurrentTest";

        // Multiple threads should get the same interned string
        String result1 = cache.intern(input);
        String result2 = cache.intern(input);
        assertSame(result1, result2);
    }

    @Test
    public void testDefaultConstructor() {
        InternCache cache = new InternCache();
        assertEquals(280, cache.size()); // Should be empty, but capacity is 280
    }

    @Test
    public void testCustomConstructor() {
        InternCache cache = new InternCache(100, 0.75f, 2);
        assertEquals(100, cache.size()); // Should be empty, but capacity is 100
    }
}

