package tools.jackson.core.util;

import static org.junit.Assert.*;
import org.junit.Test;
import tools.jackson.core.JsonParser;
import tools.jackson.core.JsonToken;
import tools.jackson.core.util.JsonParserSequence;

public class JsonParserSequenceTest {

    @Test
    public void testCreateFlattenedWithSingleParser() {
        JsonParser parser = new MockJsonParser();
        JsonParserSequence sequence = JsonParserSequence.createFlattened(false, parser, parser);
        assertEquals(1, sequence.containedParsersCount());
        assertEquals(parser, sequence.delegate());
    }

    @Test
    public void testCreateFlattenedWithTwoParsers() {
        JsonParser parser1 = new MockJsonParser();
        JsonParser parser2 = new MockJsonParser();
        JsonParserSequence sequence = JsonParserSequence.createFlattened(false, parser1, parser2);
        assertEquals(2, sequence.containedParsersCount());
        assertEquals(parser1, sequence.delegate());
    }

    @Test
    public void testCreateFlattenedWithNestedSequence() {
        JsonParser parser1 = new MockJsonParser();
        JsonParser parser2 = new MockJsonParser();
        JsonParserSequence innerSequence = JsonParserSequence.createFlattened(false, parser1, parser2);
        JsonParserSequence outerSequence = JsonParserSequence.createFlattened(false, innerSequence, parser2);
        assertEquals(3, outerSequence.containedParsersCount());
        assertEquals(parser1, outerSequence.delegate());
    }

    @Test
    public void testNextTokenWithSingleParser() throws Exception {
        JsonParser parser = new MockJsonParser();
        JsonParserSequence sequence = JsonParserSequence.createFlattened(false, parser, parser);

        // Test with existing token
        parser.setCurrentToken(JsonToken.VALUE_STRING);
        assertEquals(JsonToken.VALUE_STRING, sequence.nextToken());

        // Test with no existing token
        parser.setCurrentToken(null);
        assertEquals(JsonToken.VALUE_STRING, sequence.nextToken());
    }

    @Test
    public void testNextTokenWithMultipleParsers() throws Exception {
        JsonParser parser1 = new MockJsonParser();
        JsonParser parser2 = new MockJsonParser();
        JsonParserSequence sequence = JsonParserSequence.createFlattened(false, parser1, parser2);

        // First parser has existing token
        parser1.setCurrentToken(JsonToken.VALUE_STRING);
        assertEquals(JsonToken.VALUE_STRING, sequence.nextToken());

        // Second parser has existing token
        parser2.setCurrentToken(JsonToken.VALUE_NUMBER_INT);
        assertEquals(JsonToken.VALUE_NUMBER_INT, sequence.nextToken());

        // No more tokens
        assertNull(sequence.nextToken());
    }

    @Test
    public void testSkipChildren() throws Exception {
        JsonParser parser = new MockJsonParser();
        JsonParserSequence sequence = JsonParserSequence.createFlattened(false, parser, parser);

        // Test with START_OBJECT
        parser.setCurrentToken(JsonToken.START_OBJECT);
        assertSame(sequence, sequence.skipChildren());
        assertEquals(JsonToken.END_OBJECT, sequence.currentToken());

        // Test with START_ARRAY
        parser.setCurrentToken(JsonToken.START_ARRAY);
        assertSame(sequence, sequence.skipChildren());
        assertEquals(JsonToken.END_ARRAY, sequence.currentToken());

        // Test with non-structure token
        parser.setCurrentToken(JsonToken.VALUE_STRING);
        assertSame(sequence, sequence.skipChildren());
        assertEquals(JsonToken.VALUE_STRING, sequence.currentToken());
    }

    @Test
    public void testClose() throws Exception {
        JsonParser parser1 = new MockJsonParser();
        JsonParser parser2 = new MockJsonParser();
        JsonParserSequence sequence = JsonParserSequence.createFlattened(false, parser1, parser2);

        sequence.close();
        assertTrue(parser1.isClosed());
        assertTrue(parser2.isClosed());
    }

    @Test
    public void testContainedParsersCount() {
        JsonParser parser1 = new MockJsonParser();
        JsonParser parser2 = new MockJsonParser();
        JsonParserSequence sequence = JsonParserSequence.createFlattened(false, parser1, parser2);
        assertEquals(2, sequence.containedParsersCount());
    }

    @Test
    public void testNextName() throws Exception {
        JsonParser parser = new MockJsonParser();
        JsonParserSequence sequence = JsonParserSequence.createFlattened(false, parser, parser);

        // Test with PROPERTY_NAME
        parser.setCurrentToken(JsonToken.PROPERTY_NAME);
        parser.setCurrentName("test");
        assertEquals("test", sequence.nextName());

        // Test with non-PROPERTY_NAME
        parser.setCurrentToken(JsonToken.VALUE_STRING);
        assertNull(sequence.nextName());
    }

    @Test
    public void testNextNameWithSerializableString() throws Exception {
        JsonParser parser = new MockJsonParser();
        JsonParserSequence sequence = JsonParserSequence.createFlattened(false, parser, parser);

        // Test with matching PROPERTY_NAME
        parser.setCurrentToken(JsonToken.PROPERTY_NAME);
        parser.setCurrentName("test");
        assertTrue(sequence.nextName(new MockSerializableString("test")));

        // Test with non-matching PROPERTY_NAME
        parser.setCurrentToken(JsonToken.PROPERTY_NAME);
        parser.setCurrentName("test");
        assertFalse(sequence.nextName(new MockSerializableString("other")));

        // Test with non-PROPERTY_NAME
        parser.setCurrentToken(JsonToken.VALUE_STRING);
        assertFalse(sequence.nextName(new MockSerializableString("test")));
    }

    @Test
    public void testNextNameMatch() throws Exception {
        JsonParser parser = new MockJsonParser();
        JsonParserSequence sequence = JsonParserSequence.createFlattened(false, parser, parser);

        // Test with matching PROPERTY_NAME
        parser.setCurrentToken(JsonToken.PROPERTY_NAME);
        parser.setCurrentName("test");
        assertEquals(0, sequence.nextNameMatch(new MockPropertyNameMatcher("test")));

        // Test with non-matching PROPERTY_NAME
        parser.setCurrentToken(JsonToken.PROPERTY_NAME);
        parser.setCurrentName("test");
        assertEquals(PropertyNameMatcher.MATCH_UNKNOWN_NAME, sequence.nextNameMatch(new MockPropertyNameMatcher("other")));

        // Test with END_OBJECT
        parser.setCurrentToken(JsonToken.END_OBJECT);
        assertEquals(PropertyNameMatcher.MATCH_END_OBJECT, sequence.nextNameMatch(new MockPropertyNameMatcher("test")));

        // Test with non-PROPERTY_NAME
        parser.setCurrentToken(JsonToken.VALUE_STRING);
        assertEquals(PropertyNameMatcher.MATCH_ODD_TOKEN, sequence.nextNameMatch(new MockPropertyNameMatcher("test")));
    }

    // Mock classes for testing
    private static class MockJsonParser extends JsonParser {
        private JsonToken currentToken;
        private String currentName;

        @Override
        public JsonToken nextToken() throws Exception {
            if (currentToken == JsonToken.PROPERTY_NAME) {
                return currentToken;
            }
            return JsonToken.VALUE_STRING;
        }

        @Override
        public String currentName() {
            return currentName;
        }

        @Override
        public boolean hasCurrentToken() {
            return currentToken != null;
        }

        @Override
        public boolean hasToken(JsonToken t) {
            return currentToken == t;
        }

        @Override
        public JsonParser skipChildren() throws Exception {
            if (currentToken == JsonToken.START_OBJECT || currentToken == JsonToken.START_ARRAY) {
                currentToken = currentToken == JsonToken.START_OBJECT ? JsonToken.END_OBJECT : JsonToken.END_ARRAY;
            }
            return this;
        }

        @Override
        public String nextName() throws Exception {
            if (currentToken == JsonToken.PROPERTY_NAME) {
                return currentName;
            }
            return null;
        }

        @Override
        public boolean nextName(SerializableString str) throws Exception {
            if (currentToken == JsonToken.PROPERTY_NAME && str.getValue().equals(currentName)) {
                return true;
            }
            return false;
        }

        @Override
        public int nextNameMatch(PropertyNameMatcher matcher) throws Exception {
            if (currentToken == JsonToken.PROPERTY_NAME) {
                return matcher.matchName(currentName);
            } else if (currentToken == JsonToken.END_OBJECT) {
                return PropertyNameMatcher.MATCH_END_OBJECT;
            }
            return PropertyNameMatcher.MATCH_ODD_TOKEN;
        }

        @Override
        public void close() throws Exception {
            // Do nothing
        }

        @Override
        public boolean isClosed() {
            return false;
        }

        public void setCurrentToken(JsonToken token) {
            this.currentToken = token;
        }

        public void setCurrentName(String name) {
            this.currentName = name;
        }
    }

    private static class MockSerializableString implements SerializableString {
        private final String value;

        public MockSerializableString(String value) {
            this.value = value;
        }

        @Override
        public String getValue() {
            return value;
        }

        @Override
        public int charLength() {
            return value.length();
