package tools.jackson.core.util;

import org.junit.Test;
import static org.junit.Assert.*;
import tools.jackson.core.JacksonException;
import tools.jackson.core.JsonGenerator;
import tools.jackson.core.util.Separators.Spacing;

public class MinimalPrettyPrinterTest {

    @Test
    public void testDefaultConstructor() {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        assertEquals(" ", printer._rootValueSeparator);
        assertEquals(Spacing.NONE, printer._separators.getObjectNameValueSpacing());
    }

    @Test
    public void testConstructorWithRootValueSeparator() {
        String customSeparator = "\n";
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter(customSeparator);
        assertEquals(customSeparator, printer._rootValueSeparator);
        assertEquals(Spacing.NONE, printer._separators.getObjectNameValueSpacing());
    }

    @Test
    public void testSetRootValueSeparator() {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        String newSeparator = "\t";
        printer.setRootValueSeparator(newSeparator);
        assertEquals(newSeparator, printer._rootValueSeparator);
    }

    @Test
    public void testSetSeparators() {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        Separators newSeparators = Separators.createDefaultInstance()
            .withObjectNameValueSpacing(Spacing.BOTH);
        printer.setSeparators(newSeparators);
        assertEquals(newSeparators, printer._separators);
    }

    @Test
    public void testWriteRootValueSeparator() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        TestJsonGenerator generator = new TestJsonGenerator();
        printer.writeRootValueSeparator(generator);
        assertEquals(" ", generator.getWrittenContent());
    }

    @Test
    public void testWriteRootValueSeparatorWithCustomSeparator() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter("\n");
        TestJsonGenerator generator = new TestJsonGenerator();
        printer.writeRootValueSeparator(generator);
        assertEquals("\n", generator.getWrittenContent());
    }

    @Test
    public void testWriteStartObject() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        TestJsonGenerator generator = new TestJsonGenerator();
        printer.writeStartObject(generator);
        assertEquals("{", generator.getWrittenContent());
    }

    @Test
    public void testBeforeObjectEntries() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        TestJsonGenerator generator = new TestJsonGenerator();
        printer.beforeObjectEntries(generator);
        assertEquals("", generator.getWrittenContent());
    }

    @Test
    public void testWriteObjectNameValueSeparator() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        TestJsonGenerator generator = new TestJsonGenerator();
        printer.writeObjectNameValueSeparator(generator);
        assertEquals(":", generator.getWrittenContent());
    }

    @Test
    public void testWriteObjectEntrySeparator() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        TestJsonGenerator generator = new TestJsonGenerator();
        printer.writeObjectEntrySeparator(generator);
        assertEquals(",", generator.getWrittenContent());
    }

    @Test
    public void testWriteEndObject() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        TestJsonGenerator generator = new TestJsonGenerator();
        printer.writeEndObject(generator, 2);
        assertEquals("}", generator.getWrittenContent());
    }

    @Test
    public void testWriteStartArray() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        TestJsonGenerator generator = new TestJsonGenerator();
        printer.writeStartArray(generator);
        assertEquals("[", generator.getWrittenContent());
    }

    @Test
    public void testBeforeArrayValues() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        TestJsonGenerator generator = new TestJsonGenerator();
        printer.beforeArrayValues(generator);
        assertEquals("", generator.getWrittenContent());
    }

    @Test
    public void testWriteArrayValueSeparator() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        TestJsonGenerator generator = new TestJsonGenerator();
        printer.writeArrayValueSeparator(generator);
        assertEquals(",", generator.getWrittenContent());
    }

    @Test
    public void testWriteEndArray() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        TestJsonGenerator generator = new TestJsonGenerator();
        printer.writeEndArray(generator, 3);
        assertEquals("]", generator.getWrittenContent());
    }

    // Test helper class
    private static class TestJsonGenerator implements JsonGenerator {
        private StringBuilder content = new StringBuilder();

        @Override
        public void writeRaw(String text) throws JacksonException {
            content.append(text);
        }

        @Override
        public void writeRaw(char c) throws JacksonException {
            content.append(c);
        }

        @Override
        public void writeRaw(char[] buffer, int offset, int len) throws JacksonException {
            content.append(buffer, offset, len);
        }

        @Override
        public void writeRaw(String text, int offset, int len) throws JacksonException {
            content.append(text.substring(offset, offset + len));
        }

        @Override
        public void writeRawValue(String text) throws JacksonException {
            content.append(text);
        }

        @Override
        public void writeRawValue(String text, int offset, int len) throws JacksonException {
            content.append(text.substring(offset, offset + len));
        }

        @Override
        public void writeRawValue(char[] text, int offset, int len) throws JacksonException {
            content.append(text, offset, len);
        }

        @Override
        public void writeStartObject() throws JacksonException {
            content.append("{");
        }

        @Override
        public void writeStartObject(Object currentValue) throws JacksonException {
            content.append("{");
        }

        @Override
        public void writeStartObject(Object forValue, int size) throws JacksonException {
            content.append("{");
        }

        @Override
        public void writeEndObject() throws JacksonException {
            content.append("}");
