package tools.jackson.core.util;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import tools.jackson.core.StreamReadConstraints;
import tools.jackson.core.exc.StreamConstraintsException;
import tools.jackson.core.util.BufferRecycler;

public class ReadConstrainedTextBufferTest {

    @Test
    public void testConstructorWithValidConstraints() {
        StreamReadConstraints constraints = new StreamReadConstraints(10, 100, 1000, 100, 1000, 1000);
        BufferRecycler recycler = mock(BufferRecycler.class);
        ReadConstrainedTextBuffer buffer = new ReadConstrainedTextBuffer(constraints, recycler);
        assertNotNull(buffer);
        assertEquals(recycler, buffer.bufferRecycler());
    }

    @Test
    public void testValidateStringLengthWithinLimit() throws StreamConstraintsException {
        StreamReadConstraints constraints = new StreamReadConstraints(10, 100, 1000, 100, 1000, 1000);
        BufferRecycler recycler = mock(BufferRecycler.class);
        ReadConstrainedTextBuffer buffer = new ReadConstrainedTextBuffer(constraints, recycler);
        buffer.validateStringLength(500); // within limit (1000)
    }

    @Test(expected = StreamConstraintsException.class)
    public void testValidateStringLengthExceedsLimit() throws StreamConstraintsException {
        StreamReadConstraints constraints = new StreamReadConstraints(10, 100, 1000, 100, 1000, 1000);
        BufferRecycler recycler = mock(BufferRecycler.class);
        ReadConstrainedTextBuffer buffer = new ReadConstrainedTextBuffer(constraints, recycler);
        buffer.validateStringLength(1001); // exceeds limit (1000)
    }

    @Test
    public void testValidateStringLengthWithZeroLength() throws StreamConstraintsException {
        StreamReadConstraints constraints = new StreamReadConstraints(10, 100, 1000, 100, 1000, 1000);
        BufferRecycler recycler = mock(BufferRecycler.class);
        ReadConstrainedTextBuffer buffer = new ReadConstrainedTextBuffer(constraints, recycler);
        buffer.validateStringLength(0); // valid
    }

    @Test
    public void testValidateStringLengthWithNegativeLength() throws StreamConstraintsException {
        StreamReadConstraints constraints = new StreamReadConstraints(10, 100, 1000, 100, 1000, 1000);
        BufferRecycler recycler = mock(BufferRecycler.class);
        ReadConstrainedTextBuffer buffer = new ReadConstrainedTextBuffer(constraints, recycler);
        buffer.validateStringLength(-1); // valid (negative length is allowed)
    }
}

