package tools.jackson.core.util;

import org.junit.Test;
import static org.junit.Assert.*;
import tools.jackson.core.exc.StreamReadException;
import tools.jackson.core.json.DupDetector;

public class SimpleStreamReadContextTest {

    @Test
    public void testCreateRootContext() {
        DupDetector dups = new DupDetector(null);
        SimpleStreamReadContext rootContext = SimpleStreamReadContext.createRootContext(1, 0, dups);
        assertNotNull(rootContext);
        assertEquals(SimpleStreamReadContext.TYPE_ROOT, rootContext._type);
        assertNull(rootContext._parent);
        assertEquals(0, rootContext._nestingDepth);
        assertEquals(dups, rootContext._dups);
        assertEquals(1, rootContext._lineNr);
        assertEquals(0, rootContext._columnNr);
        assertEquals(-1, rootContext._index);
    }

    @Test
    public void testCreateRootContextWithDefaultLineNumber() {
        DupDetector dups = new DupDetector(null);
        SimpleStreamReadContext rootContext = SimpleStreamReadContext.createRootContext(dups);
        assertNotNull(rootContext);
        assertEquals(SimpleStreamReadContext.TYPE_ROOT, rootContext._type);
        assertNull(rootContext._parent);
        assertEquals(0, rootContext._nestingDepth);
        assertEquals(dups, rootContext._dups);
        assertEquals(1, rootContext._lineNr);
        assertEquals(0, rootContext._columnNr);
        assertEquals(-1, rootContext._index);
    }

    @Test
    public void testCreateChildArrayContext() {
        DupDetector parentDups = new DupDetector(null);
        SimpleStreamReadContext parentContext = SimpleStreamReadContext.createRootContext(1, 0, parentDups);
        SimpleStreamReadContext childContext = parentContext.createChildArrayContext(2, 5);

        assertNotNull(childContext);
        assertEquals(SimpleStreamReadContext.TYPE_ARRAY, childContext._type);
        assertEquals(parentContext, childContext._parent);
        assertEquals(1, childContext._nestingDepth);
        assertNotNull(childContext._dups);
        assertEquals(2, childContext._lineNr);
        assertEquals(5, childContext._columnNr);
        assertEquals(-1, childContext._index);
    }

    @Test
    public void testCreateChildObjectContext() {
        DupDetector parentDups = new DupDetector(null);
        SimpleStreamReadContext parentContext = SimpleStreamReadContext.createRootContext(1, 0, parentDups);
        SimpleStreamReadContext childContext = parentContext.createChildObjectContext(3, 10);

        assertNotNull(childContext);
        assertEquals(SimpleStreamReadContext.TYPE_OBJECT, childContext._type);
        assertEquals(parentContext, childContext._parent);
        assertEquals(1, childContext._nestingDepth);
        assertNotNull(childContext._dups);
        assertEquals(3, childContext._lineNr);
        assertEquals(10, childContext._columnNr);
        assertEquals(-1, childContext._index);
    }

    @Test
    public void testValueRead() {
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, null);
        assertEquals(-1, context._index);
        int newIndex = context.valueRead();
        assertEquals(0, newIndex);
        assertEquals(0, context._index);
    }

    @Test
    public void testRollbackValueRead() {
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, null);
        context.valueRead(); // index becomes 0
        int newIndex = context.rollbackValueRead();
        assertEquals(-1, newIndex);
        assertEquals(-1, context._index);
    }

    @Test
    public void testSetCurrentName() throws StreamReadException {
        DupDetector dups = new DupDetector(null);
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, dups);
        context.setCurrentName("testName");
        assertEquals("testName", context._currentName);
    }

    @Test(expected = StreamReadException.class)
    public void testSetDuplicateName() throws StreamReadException {
        DupDetector dups = new DupDetector(null);
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, dups);
        context.setCurrentName("testName");
        context.setCurrentName("testName"); // Should throw StreamReadException
    }

    @Test
