        buffer.append('a');
        buffer.resetWithEmpty();
        assertEquals(0, buffer.size());
        assertNull(buffer._resultString);
        assertNull(buffer._resultArray);
        assertNull(buffer._inputBuffer);
        assertEquals(-1, buffer._inputStart);
    }

    @Test
