        TextBuffer buffer = new TextBuffer(mockAllocator);
        buffer.append("123.45");
        double result = buffer.contentsAsDouble(false);
        assertEquals(123.45, result, 0.0001);
    }

    @Test
    public void testContentsAsFloat() throws NumberFormatException {
        TextBuffer buffer = new TextBuffer(mockAllocator);
        buffer.append("123.45");
        float result = buffer.contentsAsFloat(false);
