        TextBuffer buffer = new TextBuffer(mockAllocator);
        buffer.append("test");
        buffer.releaseBuffers();
        assertNull(buffer._currentSegment);
    }

    @Test
    public void testSize() {
        TextBuffer buffer = new TextBuffer(mockAllocator);
        assertEquals(0, buffer.size());
        buffer.append("test");
        assertEquals(4, buffer.size());
    }

    @Test
    public void testGetTextOffset() {
        TextBuffer buffer = new TextBuffer(mockAllocator);
        assertEquals(0, buffer.getTextOffset());
        char[] shared = new char[10];
        buffer.resetWithShared(shared, 2, 4);
        assertEquals(2, buffer.getTextOffset());
    }

