    public void testExpandCurrentSegment() {
        TextBuffer buffer = new TextBuffer(mockAllocator);
        char[] segment = buffer.expandCurrentSegment();
        assertNotNull(segment);
        assertEquals(500, segment.length); // MIN_SEGMENT_LEN
    }

    @Test
    public void testExpandCurrentSegmentWithMinSize() {
        TextBuffer buffer = new TextBuffer(mockAllocator);
        char[] segment = buffer.expandCurrentSegment(1000);
        assertNotNull(segment);
        assertEquals(1000, segment.length);
    }

    @Test
    public void testToString() {
        TextBuffer buffer = new TextBuffer(mockAllocator);
        buffer.append("test");
        assertEquals("test", buffer.toString());
    }

    @Test
